pub struct AnchorFormat3 {
	/// `XCoordinate` (Short).
	pub x_coordinate: i16,
	/// `YCoordinate` (Short).
	pub y_coordinate: i16,
	/// `XDeviceTable` (Table).
	pub x_device_table: Option<Box<Device>>,
	/// `YDeviceTable` (Table).
	pub y_device_table: Option<Box<Device>>,
}

impl Default for AnchorFormat3 {
	fn default() -> Self {
		AnchorFormat3 {
			x_coordinate: Default::default(),
			y_coordinate: Default::default(),
			x_device_table: Default::default(),
			y_device_table: Default::default(),
		}
	}
}

impl OtTable for AnchorFormat3 {
	fn class_name(&self) -> &'static str {
		"Anchor"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.x_coordinate = r.read_i16()?;
		t.y_coordinate = r.read_i16()?;
		t.x_device_table = read_offset::<Device>(r, font, 2)?;
		t.y_device_table = read_offset::<Device>(r, font, 2)?;
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		w.write_u16(3);
		let t = self;
		let _ = t;
		w.write_i16(self.x_coordinate);
		w.write_i16(self.y_coordinate);
		write_offset(
			w,
			font,
			self.x_device_table.as_deref(),
			2,
			"XDeviceTable",
			None,
		)?;
		write_offset(
			w,
			font,
			self.y_device_table.as_deref(),
			2,
			"YDeviceTable",
			None,
		)?;
		Ok(())
	}
	fn format(&self) -> Option<u16> {
		Some(3)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(
			xw,
			"XCoordinate",
			&Attrs::new(),
			self.x_coordinate.to_string(),
		);
		xml_simple(
			xw,
			"YCoordinate",
			&Attrs::new(),
			self.y_coordinate.to_string(),
		);
		xml_struct(
			xw,
			font,
			self.x_device_table.as_deref(),
			Some("XDeviceTable"),
			&Attrs::new(),
		)?;
		xml_struct(
			xw,
			font,
			self.y_device_table.as_deref(),
			Some("YDeviceTable"),
			&Attrs::new(),
		)?;
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"XCoordinate" => self.x_coordinate = parse_int::<i16>(value_attr(e)?)?,
			"YCoordinate" => self.y_coordinate = parse_int::<i16>(value_attr(e)?)?,
			"XDeviceTable" => {
				self.x_device_table = xml_read_struct::<Device>(e, font, ctx)?.map(Box::new)
			}
			"YDeviceTable" => {
				self.y_device_table = xml_read_struct::<Device>(e, font, ctx)?.map(Box::new)
			}
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.x_device_table;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		{
			let v = &mut self.y_device_table;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

