/// `AnchorGlyphData`.
#[derive(Debug, Clone, PartialEq)]
pub struct AnchorGlyphData {
	/// `AnchorPointCount` (ComputedULong).
	pub anchor_point_count: Option<u32>,
	/// `AnchorPoint` (Struct).
	pub anchor_point: Vec<AnchorPoint>,
}

impl Default for AnchorGlyphData {
	fn default() -> Self {
		AnchorGlyphData {
			anchor_point_count: Default::default(),
			anchor_point: Default::default(),
		}
	}
}

impl OtTable for AnchorGlyphData {
	fn class_name(&self) -> &'static str {
		"AnchorGlyphData"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.anchor_point_count = Some(r.read_u32()? as u32);
		{
			let n = repeat_count(
				t.anchor_point_count.map(|v| v as i64),
				0,
				"AnchorPointCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(AnchorPoint::decompile(r, font)?);
			}
			t.anchor_point = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_anchor_point_count = CountRef::new("AnchorPointCount", 4, None);
		w.write_count_reference(count_anchor_point_count.clone());
		count_anchor_point_count.set_value((self.anchor_point.len() as i64 - 0) as u64)?;
		for (i, item) in self.anchor_point.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "AnchorPointCount", self.anchor_point_count);
		for (i, item) in self.anchor_point.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("AnchorPoint"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"AnchorPointCount" => self.anchor_point_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"AnchorPoint" => self
				.anchor_point
				.push(xml_read_struct::<AnchorPoint>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.anchor_point_count = Some((self.anchor_point.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.anchor_point.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

