/// `AnchorPoints` (format-switching).
#[derive(Debug, Clone, PartialEq)]
pub enum AnchorPoints {
	/// Format 0.
	Format0(AnchorPointsFormat0),
	/// A format fontTools does not know; it has no fields.
	Unknown(u16),
}

impl Default for AnchorPoints {
	fn default() -> Self {
		Self::with_format(0)
	}
}

impl OtTable for AnchorPoints {
	fn class_name(&self) -> &'static str {
		"AnchorPoints"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let format = r.read_u16()?;
		Ok(match format {
			0 => Self::Format0(AnchorPointsFormat0::decompile(r, font)?),
			f => Self::Unknown(f),
		})
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		match self {
			Self::Format0(v) => v.compile(w, font),
			Self::Unknown(f) => {
				w.write_u16(*f);
				Ok(())
			}
		}
	}
	fn format(&self) -> Option<u16> {
		Some(match self {
			Self::Format0(_) => 0,
			Self::Unknown(f) => *f,
		})
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		match self {
			Self::Format0(v) => v.to_xml2(xw, font),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format0(v) => v.from_xml(element, font, ctx),
			Self::Unknown(_) => Err(Error::ttx(format!("KeyError: {:?}", element.name))),
		}
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format0(v) => v.populate_defaults(ctx),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		match self {
			Self::Format0(v) => v.remap_glyphs(f),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn struct_length(&self) -> Option<StructLength> {
		match self {
			Self::Format0(v) => v.struct_length(),
			Self::Unknown(_) => None,
		}
	}
	fn propagated_counts(&self) -> &'static [&'static str] {
		match self {
			Self::Format0(v) => v.propagated_counts(),
			Self::Unknown(_) => &[],
		}
	}
	fn set_propagated_count(&mut self, name: &str, value: Option<u32>) {
		match self {
			Self::Format0(v) => v.set_propagated_count(name, value),
			Self::Unknown(_) => {}
		}
	}
	fn with_format(format: u16) -> Self {
		match format {
			0 => Self::Format0(AnchorPointsFormat0::default()),
			f => Self::Unknown(f),
		}
	}
}

/// `AttachList`.
#[derive(Debug, Clone, PartialEq)]
pub struct AttachList {
	/// `Coverage` (Table).
	pub coverage: Option<Box<Coverage>>,
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `AttachPoint` (Table).
	pub attach_point: Vec<Option<Box<AttachPoint>>>,
}

impl Default for AttachList {
	fn default() -> Self {
		AttachList {
			coverage: Default::default(),
			glyph_count: Default::default(),
			attach_point: Default::default(),
		}
	}
}

impl OtTable for AttachList {
	fn class_name(&self) -> &'static str {
		"AttachList"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.coverage = read_offset::<Coverage>(r, font, 2)?;
		t.glyph_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), 0, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<AttachPoint>(r, font, 2)?);
			}
			t.attach_point = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		write_offset(w, font, self.coverage.as_deref(), 2, "Coverage", None)?;
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		count_glyph_count.set_value((self.attach_point.len() as i64 - 0) as u64)?;
		for (i, item) in self.attach_point.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 2, "AttachPoint", Some(i))?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.coverage.as_deref(),
			Some("Coverage"),
			&Attrs::new(),
		)?;
		xml_computed(xw, "GlyphCount", self.glyph_count);
		for (i, item) in self.attach_point.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("AttachPoint"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Coverage" => self.coverage = xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new),
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"AttachPoint" => self
				.attach_point
				.push(xml_read_struct::<AttachPoint>(e, font, ctx)?.map(Box::new)),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.glyph_count = Some((self.attach_point.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.coverage;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.attach_point.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

