/// `AxisValueArray`.
#[derive(Debug, Clone, PartialEq)]
pub struct AxisValueArray {
	/// `AxisValue` (Table).
	pub axis_value: Vec<Option<Box<AxisValue>>>,
}

impl Default for AxisValueArray {
	fn default() -> Self {
		AxisValueArray {
			axis_value: Default::default(),
		}
	}
}

impl OtTable for AxisValueArray {
	fn class_name(&self) -> &'static str {
		"AxisValueArray"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		{
			let n = repeat_count(
				r.get("AxisValueCount").and_then(StateValue::as_int),
				0,
				"AxisValueCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<AxisValue>(r, font, 2)?);
			}
			t.axis_value = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.count_ref("AxisValueCount")?
			.set_value((self.axis_value.len() as i64 - 0) as u64)?;
		for (i, item) in self.axis_value.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 2, "AxisValue", Some(i))?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		for (i, item) in self.axis_value.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("AxisValue"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"AxisValue" => self
				.axis_value
				.push(xml_read_struct::<AxisValue>(e, font, ctx)?.map(Box::new)),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		ctx.set_count(
			"AxisValueCount",
			(self.axis_value.len() as i64 - 0).max(0) as u32,
		)?;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.axis_value.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

