/// `BASE`.
#[derive(Debug, Clone, PartialEq)]
pub struct BASE {
	/// `Version` (Version).
	pub version: u32,
	/// `HorizAxis` (Table).
	pub horiz_axis: Option<Box<Axis>>,
	/// `VertAxis` (Table).
	pub vert_axis: Option<Box<Axis>>,
	/// `VarStore` (LTable).
	pub var_store: Option<Box<VarStore>>,
}

impl Default for BASE {
	fn default() -> Self {
		BASE {
			version: Default::default(),
			horiz_axis: Default::default(),
			vert_axis: Default::default(),
			var_store: Default::default(),
		}
	}
}

impl OtTable for BASE {
	fn class_name(&self) -> &'static str {
		"BASE"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.version = r.read_u32()?;
		t.horiz_axis = read_offset::<Axis>(r, font, 2)?;
		t.vert_axis = read_offset::<Axis>(r, font, 2)?;
		if (t.version as i64) >= 0x00010001 {
			t.var_store = read_offset::<VarStore>(r, font, 4)?;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.write_u32(version_as_long(self.version)?);
		write_offset(w, font, self.horiz_axis.as_deref(), 2, "HorizAxis", None)?;
		write_offset(w, font, self.vert_axis.as_deref(), 2, "VertAxis", None)?;
		if (t.version as i64) >= 0x00010001 {
			write_offset(w, font, self.var_store.as_deref(), 4, "VarStore", None)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(
			xw,
			"Version",
			&Attrs::new(),
			format!("0x{:08x}", self.version),
		);
		xml_struct(
			xw,
			font,
			self.horiz_axis.as_deref(),
			Some("HorizAxis"),
			&Attrs::new(),
		)?;
		xml_struct(
			xw,
			font,
			self.vert_axis.as_deref(),
			Some("VertAxis"),
			&Attrs::new(),
		)?;
		if (t.version as i64) >= 0x00010001 {
			xml_struct(
				xw,
				font,
				self.var_store.as_deref(),
				Some("VarStore"),
				&Attrs::new(),
			)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Version" => self.version = parse_version(value_attr(e)?)?,
			"HorizAxis" => self.horiz_axis = xml_read_struct::<Axis>(e, font, ctx)?.map(Box::new),
			"VertAxis" => self.vert_axis = xml_read_struct::<Axis>(e, font, ctx)?.map(Box::new),
			"VarStore" => self.var_store = xml_read_struct::<VarStore>(e, font, ctx)?.map(Box::new),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.horiz_axis;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		{
			let v = &mut self.vert_axis;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		if (self.version as i64) >= 0x00010001 {
			{
				let v = &mut self.var_store;
				if let Some(x) = v {
					x.remap_glyphs(&mut *f)?;
				}
			}
		}
		Ok(())
	}
}

/// `BaseArray`.
#[derive(Debug, Clone, PartialEq)]
pub struct BaseArray {
	/// `BaseCount` (ComputedUShort).
	pub base_count: Option<u32>,
	/// `BaseRecord` (Struct).
	pub base_record: Vec<BaseRecord>,
}

impl Default for BaseArray {
	fn default() -> Self {
		BaseArray {
			base_count: Default::default(),
			base_record: Default::default(),
		}
	}
}

impl OtTable for BaseArray {
	fn class_name(&self) -> &'static str {
		"BaseArray"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.base_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.base_count.map(|v| v as i64), 0, "BaseCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(BaseRecord::decompile(r, font)?);
			}
			t.base_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_base_count = CountRef::new("BaseCount", 2, None);
		w.write_count_reference(count_base_count.clone());
		count_base_count.set_value((self.base_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.base_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "BaseCount", self.base_count);
		for (i, item) in self.base_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("BaseRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"BaseCount" => self.base_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"BaseRecord" => self
				.base_record
				.push(xml_read_struct::<BaseRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.base_count = Some((self.base_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.base_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

