/// `BaseCoord` (format-switching).
#[derive(Debug, Clone, PartialEq)]
pub enum BaseCoord {
	/// Format 1.
	Format1(BaseCoordFormat1),
	/// Format 2.
	Format2(BaseCoordFormat2),
	/// Format 3.
	Format3(BaseCoordFormat3),
	/// Format 4.
	Format4(BaseCoordFormat4),
	/// A format fontTools does not know; it has no fields.
	Unknown(u16),
}

impl Default for BaseCoord {
	fn default() -> Self {
		Self::with_format(1)
	}
}

impl OtTable for BaseCoord {
	fn class_name(&self) -> &'static str {
		"BaseCoord"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let format = r.read_u16()?;
		Ok(match format {
			1 => Self::Format1(BaseCoordFormat1::decompile(r, font)?),
			2 => Self::Format2(BaseCoordFormat2::decompile(r, font)?),
			3 => Self::Format3(BaseCoordFormat3::decompile(r, font)?),
			4 => Self::Format4(BaseCoordFormat4::decompile(r, font)?),
			f => Self::Unknown(f),
		})
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		match self {
			Self::Format1(v) => v.compile(w, font),
			Self::Format2(v) => v.compile(w, font),
			Self::Format3(v) => v.compile(w, font),
			Self::Format4(v) => v.compile(w, font),
			Self::Unknown(f) => {
				w.write_u16(*f);
				Ok(())
			}
		}
	}
	fn format(&self) -> Option<u16> {
		Some(match self {
			Self::Format1(_) => 1,
			Self::Format2(_) => 2,
			Self::Format3(_) => 3,
			Self::Format4(_) => 4,
			Self::Unknown(f) => *f,
		})
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		match self {
			Self::Format1(v) => v.to_xml2(xw, font),
			Self::Format2(v) => v.to_xml2(xw, font),
			Self::Format3(v) => v.to_xml2(xw, font),
			Self::Format4(v) => v.to_xml2(xw, font),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format1(v) => v.from_xml(element, font, ctx),
			Self::Format2(v) => v.from_xml(element, font, ctx),
			Self::Format3(v) => v.from_xml(element, font, ctx),
			Self::Format4(v) => v.from_xml(element, font, ctx),
			Self::Unknown(_) => Err(Error::ttx(format!("KeyError: {:?}", element.name))),
		}
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format1(v) => v.populate_defaults(ctx),
			Self::Format2(v) => v.populate_defaults(ctx),
			Self::Format3(v) => v.populate_defaults(ctx),
			Self::Format4(v) => v.populate_defaults(ctx),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		match self {
			Self::Format1(v) => v.remap_glyphs(f),
			Self::Format2(v) => v.remap_glyphs(f),
			Self::Format3(v) => v.remap_glyphs(f),
			Self::Format4(v) => v.remap_glyphs(f),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn struct_length(&self) -> Option<StructLength> {
		match self {
			Self::Format1(v) => v.struct_length(),
			Self::Format2(v) => v.struct_length(),
			Self::Format3(v) => v.struct_length(),
			Self::Format4(v) => v.struct_length(),
			Self::Unknown(_) => None,
		}
	}
	fn propagated_counts(&self) -> &'static [&'static str] {
		match self {
			Self::Format1(v) => v.propagated_counts(),
			Self::Format2(v) => v.propagated_counts(),
			Self::Format3(v) => v.propagated_counts(),
			Self::Format4(v) => v.propagated_counts(),
			Self::Unknown(_) => &[],
		}
	}
	fn set_propagated_count(&mut self, name: &str, value: Option<u32>) {
		match self {
			Self::Format1(v) => v.set_propagated_count(name, value),
			Self::Format2(v) => v.set_propagated_count(name, value),
			Self::Format3(v) => v.set_propagated_count(name, value),
			Self::Format4(v) => v.set_propagated_count(name, value),
			Self::Unknown(_) => {}
		}
	}
	fn with_format(format: u16) -> Self {
		match format {
			1 => Self::Format1(BaseCoordFormat1::default()),
			2 => Self::Format2(BaseCoordFormat2::default()),
			3 => Self::Format3(BaseCoordFormat3::default()),
			4 => Self::Format4(BaseCoordFormat4::default()),
			f => Self::Unknown(f),
		}
	}
}

/// `BaseGlyphList`.
#[derive(Debug, Clone, PartialEq)]
pub struct BaseGlyphList {
	/// `BaseGlyphCount` (ComputedULong).
	pub base_glyph_count: Option<u32>,
	/// `BaseGlyphPaintRecord` (Struct).
	pub base_glyph_paint_record: Vec<BaseGlyphPaintRecord>,
}

impl Default for BaseGlyphList {
	fn default() -> Self {
		BaseGlyphList {
			base_glyph_count: Default::default(),
			base_glyph_paint_record: Default::default(),
		}
	}
}

impl OtTable for BaseGlyphList {
	fn class_name(&self) -> &'static str {
		"BaseGlyphList"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.base_glyph_count = Some(r.read_u32()? as u32);
		{
			let n = repeat_count(t.base_glyph_count.map(|v| v as i64), 0, "BaseGlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(BaseGlyphPaintRecord::decompile(r, font)?);
			}
			t.base_glyph_paint_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if !self
			.base_glyph_paint_record
			.is_sorted_by_key(|r| r.base_glyph)
		{
			let mut c = self.clone();
			c.base_glyph_paint_record.sort_by_key(|r| r.base_glyph);
			return c.compile(w, font);
		}
		let t = self;
		let _ = t;
		let count_base_glyph_count = CountRef::new("BaseGlyphCount", 4, None);
		w.write_count_reference(count_base_glyph_count.clone());
		count_base_glyph_count.set_value((self.base_glyph_paint_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.base_glyph_paint_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "BaseGlyphCount", self.base_glyph_count);
		for (i, item) in self.base_glyph_paint_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("BaseGlyphPaintRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"BaseGlyphCount" => self.base_glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"BaseGlyphPaintRecord" => self
				.base_glyph_paint_record
				.push(xml_read_struct::<BaseGlyphPaintRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.base_glyph_count = Some((self.base_glyph_paint_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.base_glyph_paint_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

/// `BaseGlyphPaintRecord`.
#[derive(Debug, Clone, PartialEq)]
