/// `BaseGlyphRecordArray`.
#[derive(Debug, Clone, PartialEq)]
pub struct BaseGlyphRecordArray {
	/// `BaseGlyphRecord` (Struct).
	pub base_glyph_record: Vec<BaseGlyphRecord>,
}

impl Default for BaseGlyphRecordArray {
	fn default() -> Self {
		BaseGlyphRecordArray {
			base_glyph_record: Default::default(),
		}
	}
}

impl OtTable for BaseGlyphRecordArray {
	fn class_name(&self) -> &'static str {
		"BaseGlyphRecordArray"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		{
			let n = repeat_count(
				r.get("BaseGlyphRecordCount").and_then(StateValue::as_int),
				0,
				"BaseGlyphRecordCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(BaseGlyphRecord::decompile(r, font)?);
			}
			t.base_glyph_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if !self.base_glyph_record.is_sorted_by_key(|r| r.base_glyph) {
			let mut c = self.clone();
			c.base_glyph_record.sort_by_key(|r| r.base_glyph);
			return c.compile(w, font);
		}
		let t = self;
		let _ = t;
		w.count_ref("BaseGlyphRecordCount")?
			.set_value((self.base_glyph_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.base_glyph_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		for (i, item) in self.base_glyph_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("BaseGlyphRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"BaseGlyphRecord" => self
				.base_glyph_record
				.push(xml_read_struct::<BaseGlyphRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		ctx.set_count(
			"BaseGlyphRecordCount",
			(self.base_glyph_record.len() as i64 - 0).max(0) as u32,
		)?;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.base_glyph_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

