/// `BaseScript`.
#[derive(Debug, Clone, PartialEq)]
pub struct BaseScript {
	/// `BaseValues` (Table).
	pub base_values: Option<Box<BaseValues>>,
	/// `DefaultMinMax` (Table).
	pub default_min_max: Option<Box<MinMax>>,
	/// `BaseLangSysCount` (ComputedUShort).
	pub base_lang_sys_count: Option<u32>,
	/// `BaseLangSysRecord` (Struct).
	pub base_lang_sys_record: Vec<BaseLangSysRecord>,
}

impl Default for BaseScript {
	fn default() -> Self {
		BaseScript {
			base_values: Default::default(),
			default_min_max: Default::default(),
			base_lang_sys_count: Default::default(),
			base_lang_sys_record: Default::default(),
		}
	}
}

impl OtTable for BaseScript {
	fn class_name(&self) -> &'static str {
		"BaseScript"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.base_values = read_offset::<BaseValues>(r, font, 2)?;
		t.default_min_max = read_offset::<MinMax>(r, font, 2)?;
		t.base_lang_sys_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(
				t.base_lang_sys_count.map(|v| v as i64),
				0,
				"BaseLangSysCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(BaseLangSysRecord::decompile(r, font)?);
			}
			t.base_lang_sys_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		write_offset(w, font, self.base_values.as_deref(), 2, "BaseValues", None)?;
		write_offset(
			w,
			font,
			self.default_min_max.as_deref(),
			2,
			"DefaultMinMax",
			None,
		)?;
		let count_base_lang_sys_count = CountRef::new("BaseLangSysCount", 2, None);
		w.write_count_reference(count_base_lang_sys_count.clone());
		count_base_lang_sys_count.set_value((self.base_lang_sys_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.base_lang_sys_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.base_values.as_deref(),
			Some("BaseValues"),
			&Attrs::new(),
		)?;
		xml_struct(
			xw,
			font,
			self.default_min_max.as_deref(),
			Some("DefaultMinMax"),
			&Attrs::new(),
		)?;
		xml_computed(xw, "BaseLangSysCount", self.base_lang_sys_count);
		for (i, item) in self.base_lang_sys_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("BaseLangSysRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"BaseValues" => {
				self.base_values = xml_read_struct::<BaseValues>(e, font, ctx)?.map(Box::new)
			}
			"DefaultMinMax" => {
				self.default_min_max = xml_read_struct::<MinMax>(e, font, ctx)?.map(Box::new)
			}
			"BaseLangSysCount" => {
				self.base_lang_sys_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"BaseLangSysRecord" => self
				.base_lang_sys_record
				.push(xml_read_struct::<BaseLangSysRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.base_lang_sys_count = Some((self.base_lang_sys_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.base_values;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		{
			let v = &mut self.default_min_max;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.base_lang_sys_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

