		let t = self;
		let _ = t;
		w.write_u16(self.data_format);
		let count_struct_length = CountRef::new("StructLength", 4, None);
		w.write_count_reference(count_struct_length.clone());
		w.write_u16(self.registry);
		write_char64(w, &self.registry_name);
		w.write_u16(self.order);
		write_char64(w, &self.order_name);
