/// `ChainPosClassRule`.
#[derive(Debug, Clone, PartialEq)]
pub struct ChainPosClassRule {
	/// `BacktrackGlyphCount` (ComputedUShort).
	pub backtrack_glyph_count: Option<u32>,
	/// `Backtrack` (UShort).
	pub backtrack: Vec<u16>,
	/// `InputGlyphCount` (ComputedUShort).
	pub input_glyph_count: Option<u32>,
	/// `Input` (UShort).
	pub input: Vec<u16>,
	/// `LookAheadGlyphCount` (ComputedUShort).
	pub look_ahead_glyph_count: Option<u32>,
	/// `LookAhead` (UShort).
	pub look_ahead: Vec<u16>,
	/// `PosCount` (ComputedUShort).
	pub pos_count: Option<u32>,
	/// `PosLookupRecord` (Struct).
	pub pos_lookup_record: Vec<PosLookupRecord>,
}

impl Default for ChainPosClassRule {
	fn default() -> Self {
		ChainPosClassRule {
			backtrack_glyph_count: Default::default(),
			backtrack: Default::default(),
			input_glyph_count: Default::default(),
			input: Default::default(),
			look_ahead_glyph_count: Default::default(),
			look_ahead: Default::default(),
			pos_count: Default::default(),
			pos_lookup_record: Default::default(),
		}
	}
}

impl OtTable for ChainPosClassRule {
	fn class_name(&self) -> &'static str {
		"ChainPosClassRule"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.backtrack_glyph_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(
				t.backtrack_glyph_count.map(|v| v as i64),
				0,
				"BacktrackGlyphCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.backtrack = v;
		}
		t.input_glyph_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.input_glyph_count.map(|v| v as i64), -1, "InputGlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.input = v;
		}
		t.look_ahead_glyph_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(
				t.look_ahead_glyph_count.map(|v| v as i64),
				0,
				"LookAheadGlyphCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.look_ahead = v;
		}
		t.pos_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.pos_count.map(|v| v as i64), 0, "PosCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(PosLookupRecord::decompile(r, font)?);
			}
			t.pos_lookup_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_backtrack_glyph_count = CountRef::new("BacktrackGlyphCount", 2, None);
		w.write_count_reference(count_backtrack_glyph_count.clone());
		count_backtrack_glyph_count.set_value((self.backtrack.len() as i64 - 0) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.backtrack.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		let count_input_glyph_count = CountRef::new("InputGlyphCount", 2, None);
		w.write_count_reference(count_input_glyph_count.clone());
		count_input_glyph_count.set_value((self.input.len() as i64 - -1) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.input.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		let count_look_ahead_glyph_count = CountRef::new("LookAheadGlyphCount", 2, None);
		w.write_count_reference(count_look_ahead_glyph_count.clone());
		count_look_ahead_glyph_count.set_value((self.look_ahead.len() as i64 - 0) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.look_ahead.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		let count_pos_count = CountRef::new("PosCount", 2, None);
		w.write_count_reference(count_pos_count.clone());
		count_pos_count.set_value((self.pos_lookup_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.pos_lookup_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "BacktrackGlyphCount", self.backtrack_glyph_count);
		for (i, item) in self.backtrack.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "Backtrack", &attrs, (*item).to_string());
		}
		xml_computed(xw, "InputGlyphCount", self.input_glyph_count);
		for (i, item) in self.input.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "Input", &attrs, (*item).to_string());
		}
		xml_computed(xw, "LookAheadGlyphCount", self.look_ahead_glyph_count);
		for (i, item) in self.look_ahead.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "LookAhead", &attrs, (*item).to_string());
		}
		xml_computed(xw, "PosCount", self.pos_count);
		for (i, item) in self.pos_lookup_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("PosLookupRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"BacktrackGlyphCount" => {
				self.backtrack_glyph_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"Backtrack" => self.backtrack.push(parse_int::<u16>(value_attr(e)?)?),
			"InputGlyphCount" => self.input_glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"Input" => self.input.push(parse_int::<u16>(value_attr(e)?)?),
			"LookAheadGlyphCount" => {
				self.look_ahead_glyph_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"LookAhead" => self.look_ahead.push(parse_int::<u16>(value_attr(e)?)?),
			"PosCount" => self.pos_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"PosLookupRecord" => self
				.pos_lookup_record
				.push(xml_read_struct::<PosLookupRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.backtrack_glyph_count = Some((self.backtrack.len() as i64 - 0).max(0) as u32);
		self.input_glyph_count = Some((self.input.len() as i64 - -1).max(0) as u32);
		self.look_ahead_glyph_count = Some((self.look_ahead.len() as i64 - 0).max(0) as u32);
		self.pos_count = Some((self.pos_lookup_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.pos_lookup_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

