/// `ClassSeqRule`.
#[derive(Debug, Clone, PartialEq)]
pub struct ClassSeqRule {
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `SeqLookupCount` (ComputedUShort).
	pub seq_lookup_count: Option<u32>,
	/// `InputSequence` (UShort).
	pub input_sequence: Vec<u16>,
	/// `SeqLookupRecord` (Struct).
	pub seq_lookup_record: Vec<SeqLookup>,
}

impl Default for ClassSeqRule {
	fn default() -> Self {
		ClassSeqRule {
			glyph_count: Default::default(),
			seq_lookup_count: Default::default(),
			input_sequence: Default::default(),
			seq_lookup_record: Default::default(),
		}
	}
}

impl OtTable for ClassSeqRule {
	fn class_name(&self) -> &'static str {
		"ClassSeqRule"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.glyph_count = Some(r.read_u16()? as u32);
		t.seq_lookup_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), -1, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.input_sequence = v;
		}
		{
			let n = repeat_count(t.seq_lookup_count.map(|v| v as i64), 0, "SeqLookupCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(SeqLookup::decompile(r, font)?);
			}
			t.seq_lookup_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		let count_seq_lookup_count = CountRef::new("SeqLookupCount", 2, None);
		w.write_count_reference(count_seq_lookup_count.clone());
		count_glyph_count.set_value((self.input_sequence.len() as i64 - -1) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.input_sequence.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		count_seq_lookup_count.set_value((self.seq_lookup_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.seq_lookup_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "GlyphCount", self.glyph_count);
		xml_computed(xw, "SeqLookupCount", self.seq_lookup_count);
		for (i, item) in self.input_sequence.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "InputSequence", &attrs, (*item).to_string());
		}
		for (i, item) in self.seq_lookup_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("SeqLookupRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"SeqLookupCount" => self.seq_lookup_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"InputSequence" => self.input_sequence.push(parse_int::<u16>(value_attr(e)?)?),
			"SeqLookupRecord" => self
				.seq_lookup_record
				.push(xml_read_struct::<SeqLookup>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.glyph_count = Some((self.input_sequence.len() as i64 - -1).max(0) as u32);
		self.seq_lookup_count = Some((self.seq_lookup_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.seq_lookup_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

