/// `ClipList` format 1.
#[doc(hidden)]
#[derive(Debug, Clone, PartialEq)]
pub struct ClipListRawFormat1 {
	/// `ClipCount` (ComputedULong).
	pub clip_count: Option<u32>,
	/// `ClipRecord` (Struct).
	pub clip_record: Vec<ClipRecord>,
}

impl Default for ClipListRawFormat1 {
	fn default() -> Self {
		ClipListRawFormat1 {
			clip_count: Default::default(),
			clip_record: Default::default(),
		}
	}
}

impl OtTable for ClipListRawFormat1 {
	fn class_name(&self) -> &'static str {
		"ClipList"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.clip_count = Some(r.read_u32()? as u32);
		{
			let n = repeat_count(t.clip_count.map(|v| v as i64), 0, "ClipCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(ClipRecord::decompile(r, font)?);
			}
			t.clip_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		w.write_u8(1);
		let t = self;
		let _ = t;
		let count_clip_count = CountRef::new("ClipCount", 4, None);
		w.write_count_reference(count_clip_count.clone());
		count_clip_count.set_value((self.clip_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.clip_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn format(&self) -> Option<u16> {
		Some(1)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "ClipCount", self.clip_count);
		for (i, item) in self.clip_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("ClipRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"ClipCount" => self.clip_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"ClipRecord" => self
				.clip_record
				.push(xml_read_struct::<ClipRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.clip_count = Some((self.clip_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.clip_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

