/// `ContextSubst` format 1.
#[derive(Debug, Clone, PartialEq)]
pub struct ContextSubstFormat1 {
	/// `Coverage` (Table).
	pub coverage: Option<Box<Coverage>>,
	/// `SubRuleSetCount` (ComputedUShort).
	pub sub_rule_set_count: Option<u32>,
	/// `SubRuleSet` (Table).
	pub sub_rule_set: Vec<Option<Box<SubRuleSet>>>,
	/// Whether the subtables below are never shared (`DontShare`), set when
	/// resolving offset overflows.
	pub dont_share: bool,
}

impl Default for ContextSubstFormat1 {
	fn default() -> Self {
		ContextSubstFormat1 {
			coverage: Default::default(),
			sub_rule_set_count: Default::default(),
			sub_rule_set: Default::default(),
			dont_share: false,
		}
	}
}

impl OtTable for ContextSubstFormat1 {
	fn class_name(&self) -> &'static str {
		"ContextSubst"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.coverage = read_offset::<Coverage>(r, font, 2)?;
		t.sub_rule_set_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.sub_rule_set_count.map(|v| v as i64), 0, "SubRuleSetCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<SubRuleSet>(r, font, 2)?);
			}
			t.sub_rule_set = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if self.dont_share {
			w.set_dont_share();
		}
		w.count_ref("LookupType")?.set_value(5)?;
		w.write_u16(1);
		let t = self;
		let _ = t;
		write_offset(w, font, self.coverage.as_deref(), 2, "Coverage", None)?;
		let count_sub_rule_set_count = CountRef::new("SubRuleSetCount", 2, None);
		w.write_count_reference(count_sub_rule_set_count.clone());
		count_sub_rule_set_count.set_value((self.sub_rule_set.len() as i64 - 0) as u64)?;
		for (i, item) in self.sub_rule_set.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 2, "SubRuleSet", Some(i))?;
		}
		Ok(())
	}
	fn dont_share(&self) -> bool {
		self.dont_share
	}
	fn set_dont_share(&mut self) {
		self.dont_share = true;
	}
	fn format(&self) -> Option<u16> {
		Some(1)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.coverage.as_deref(),
			Some("Coverage"),
			&Attrs::new(),
		)?;
		xml_computed(xw, "SubRuleSetCount", self.sub_rule_set_count);
		for (i, item) in self.sub_rule_set.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("SubRuleSet"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Coverage" => self.coverage = xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new),
			"SubRuleSetCount" => self.sub_rule_set_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"SubRuleSet" => self
				.sub_rule_set
				.push(xml_read_struct::<SubRuleSet>(e, font, ctx)?.map(Box::new)),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.sub_rule_set_count = Some((self.sub_rule_set.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.coverage;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.sub_rule_set.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

