/// `ContextSubst` format 3.
#[derive(Debug, Clone, PartialEq)]
pub struct ContextSubstFormat3 {
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `SubstCount` (ComputedUShort).
	pub subst_count: Option<u32>,
	/// `Coverage` (Table).
	pub coverage: Vec<Option<Box<Coverage>>>,
	/// `SubstLookupRecord` (Struct).
	pub subst_lookup_record: Vec<SubstLookupRecord>,
	/// Whether the subtables below are never shared (`DontShare`), set when
	/// resolving offset overflows.
	pub dont_share: bool,
}

impl Default for ContextSubstFormat3 {
	fn default() -> Self {
		ContextSubstFormat3 {
			glyph_count: Default::default(),
			subst_count: Default::default(),
			coverage: Default::default(),
			subst_lookup_record: Default::default(),
			dont_share: false,
		}
	}
}

impl OtTable for ContextSubstFormat3 {
	fn class_name(&self) -> &'static str {
		"ContextSubst"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.glyph_count = Some(r.read_u16()? as u32);
		t.subst_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), 0, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<Coverage>(r, font, 2)?);
			}
			t.coverage = v;
		}
		{
			let n = repeat_count(t.subst_count.map(|v| v as i64), 0, "SubstCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(SubstLookupRecord::decompile(r, font)?);
			}
			t.subst_lookup_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if self.dont_share {
			w.set_dont_share();
		}
		w.count_ref("LookupType")?.set_value(5)?;
		w.write_u16(3);
		let t = self;
		let _ = t;
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		let count_subst_count = CountRef::new("SubstCount", 2, None);
		w.write_count_reference(count_subst_count.clone());
		count_glyph_count.set_value((self.coverage.len() as i64 - 0) as u64)?;
		for (i, item) in self.coverage.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 2, "Coverage", Some(i))?;
		}
		count_subst_count.set_value((self.subst_lookup_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.subst_lookup_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn dont_share(&self) -> bool {
		self.dont_share
	}
	fn set_dont_share(&mut self) {
		self.dont_share = true;
	}
	fn format(&self) -> Option<u16> {
		Some(3)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "GlyphCount", self.glyph_count);
		xml_computed(xw, "SubstCount", self.subst_count);
		for (i, item) in self.coverage.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("Coverage"), &attrs)?;
		}
		for (i, item) in self.subst_lookup_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("SubstLookupRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"SubstCount" => self.subst_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"Coverage" => self
				.coverage
				.push(xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new)),
			"SubstLookupRecord" => self
				.subst_lookup_record
				.push(xml_read_struct::<SubstLookupRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.glyph_count = Some((self.coverage.len() as i64 - 0).max(0) as u32);
		self.subst_count = Some((self.subst_lookup_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.coverage.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.subst_lookup_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

