		for (i, item) in self.class_seq_rule_set.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("ClassSeqRuleSet"), &attrs)?;
		}
