/// `ContextSubst` format 6.
#[derive(Debug, Clone, PartialEq)]
pub struct ContextSubstFormat6 {
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `SeqLookupCount` (ComputedUShort).
	pub seq_lookup_count: Option<u32>,
	/// `Coverage` (Table24).
	pub coverage: Vec<Option<Box<Coverage>>>,
	/// `SeqLookupRecord` (Struct).
	pub seq_lookup_record: Vec<SeqLookup>,
	/// Whether the subtables below are never shared (`DontShare`), set when
	/// resolving offset overflows.
	pub dont_share: bool,
}

impl Default for ContextSubstFormat6 {
	fn default() -> Self {
		ContextSubstFormat6 {
			glyph_count: Default::default(),
			seq_lookup_count: Default::default(),
			coverage: Default::default(),
			seq_lookup_record: Default::default(),
			dont_share: false,
		}
	}
}

impl OtTable for ContextSubstFormat6 {
	fn class_name(&self) -> &'static str {
		"ContextSubst"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.glyph_count = Some(r.read_u16()? as u32);
		t.seq_lookup_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), 0, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<Coverage>(r, font, 3)?);
			}
			t.coverage = v;
		}
		{
			let n = repeat_count(t.seq_lookup_count.map(|v| v as i64), 0, "SeqLookupCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(SeqLookup::decompile(r, font)?);
			}
			t.seq_lookup_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if self.dont_share {
			w.set_dont_share();
		}
		w.count_ref("LookupType")?.set_value(5)?;
		w.write_u16(6);
		let t = self;
		let _ = t;
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		let count_seq_lookup_count = CountRef::new("SeqLookupCount", 2, None);
		w.write_count_reference(count_seq_lookup_count.clone());
		count_glyph_count.set_value((self.coverage.len() as i64 - 0) as u64)?;
		for (i, item) in self.coverage.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 3, "Coverage", Some(i))?;
		}
		count_seq_lookup_count.set_value((self.seq_lookup_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.seq_lookup_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn dont_share(&self) -> bool {
		self.dont_share
	}
	fn set_dont_share(&mut self) {
		self.dont_share = true;
	}
	fn format(&self) -> Option<u16> {
		Some(6)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "GlyphCount", self.glyph_count);
		xml_computed(xw, "SeqLookupCount", self.seq_lookup_count);
		for (i, item) in self.coverage.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("Coverage"), &attrs)?;
		}
		for (i, item) in self.seq_lookup_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("SeqLookupRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"SeqLookupCount" => self.seq_lookup_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"Coverage" => self
				.coverage
				.push(xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new)),
			"SeqLookupRecord" => self
				.seq_lookup_record
				.push(xml_read_struct::<SeqLookup>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.glyph_count = Some((self.coverage.len() as i64 - 0).max(0) as u32);
		self.seq_lookup_count = Some((self.seq_lookup_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.coverage.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.seq_lookup_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

/// `ContextSubst` (format-switching).
#[derive(Debug, Clone, PartialEq)]
pub enum ContextSubst {
	/// Format 1.
	Format1(ContextSubstFormat1),
	/// Format 2.
	Format2(ContextSubstFormat2),
	/// Format 3.
	Format3(ContextSubstFormat3),
	/// Format 4.
	Format4(ContextSubstFormat4),
	/// Format 5.
	Format5(ContextSubstFormat5),
	/// Format 6.
	Format6(ContextSubstFormat6),
	/// A format fontTools does not know; it has no fields.
	Unknown(u16),
}

impl Default for ContextSubst {
	fn default() -> Self {
		Self::with_format(1)
	}
}

impl OtTable for ContextSubst {
	fn class_name(&self) -> &'static str {
		"ContextSubst"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let format = r.read_u16()?;
		Ok(match format {
			1 => Self::Format1(ContextSubstFormat1::decompile(r, font)?),
			2 => Self::Format2(ContextSubstFormat2::decompile(r, font)?),
			3 => Self::Format3(ContextSubstFormat3::decompile(r, font)?),
			4 => Self::Format4(ContextSubstFormat4::decompile(r, font)?),
			5 => Self::Format5(ContextSubstFormat5::decompile(r, font)?),
			6 => Self::Format6(ContextSubstFormat6::decompile(r, font)?),
			f => Self::Unknown(f),
		})
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		match self {
			Self::Format1(v) => v.compile(w, font),
			Self::Format2(v) => v.compile(w, font),
			Self::Format3(v) => v.compile(w, font),
			Self::Format4(v) => v.compile(w, font),
			Self::Format5(v) => v.compile(w, font),
			Self::Format6(v) => v.compile(w, font),
			Self::Unknown(f) => {
				w.write_u16(*f);
				Ok(())
			}
		}
	}
	fn format(&self) -> Option<u16> {
		Some(match self {
			Self::Format1(_) => 1,
			Self::Format2(_) => 2,
			Self::Format3(_) => 3,
			Self::Format4(_) => 4,
			Self::Format5(_) => 5,
			Self::Format6(_) => 6,
			Self::Unknown(f) => *f,
		})
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		match self {
			Self::Format1(v) => v.to_xml2(xw, font),
			Self::Format2(v) => v.to_xml2(xw, font),
			Self::Format3(v) => v.to_xml2(xw, font),
			Self::Format4(v) => v.to_xml2(xw, font),
			Self::Format5(v) => v.to_xml2(xw, font),
			Self::Format6(v) => v.to_xml2(xw, font),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format1(v) => v.from_xml(element, font, ctx),
			Self::Format2(v) => v.from_xml(element, font, ctx),
			Self::Format3(v) => v.from_xml(element, font, ctx),
			Self::Format4(v) => v.from_xml(element, font, ctx),
			Self::Format5(v) => v.from_xml(element, font, ctx),
			Self::Format6(v) => v.from_xml(element, font, ctx),
			Self::Unknown(_) => Err(Error::ttx(format!("KeyError: {:?}", element.name))),
		}
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format1(v) => v.populate_defaults(ctx),
			Self::Format2(v) => v.populate_defaults(ctx),
			Self::Format3(v) => v.populate_defaults(ctx),
			Self::Format4(v) => v.populate_defaults(ctx),
			Self::Format5(v) => v.populate_defaults(ctx),
			Self::Format6(v) => v.populate_defaults(ctx),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		match self {
			Self::Format1(v) => v.remap_glyphs(f),
			Self::Format2(v) => v.remap_glyphs(f),
			Self::Format3(v) => v.remap_glyphs(f),
			Self::Format4(v) => v.remap_glyphs(f),
			Self::Format5(v) => v.remap_glyphs(f),
			Self::Format6(v) => v.remap_glyphs(f),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn dont_share(&self) -> bool {
		match self {
			Self::Format1(v) => v.dont_share(),
			Self::Format2(v) => v.dont_share(),
			Self::Format3(v) => v.dont_share(),
			Self::Format4(v) => v.dont_share(),
			Self::Format5(v) => v.dont_share(),
			Self::Format6(v) => v.dont_share(),
			Self::Unknown(_) => false,
		}
	}
	fn set_dont_share(&mut self) {
		match self {
			Self::Format1(v) => v.set_dont_share(),
			Self::Format2(v) => v.set_dont_share(),
			Self::Format3(v) => v.set_dont_share(),
			Self::Format4(v) => v.set_dont_share(),
			Self::Format5(v) => v.set_dont_share(),
			Self::Format6(v) => v.set_dont_share(),
			Self::Unknown(_) => {}
		}
	}
	fn struct_length(&self) -> Option<StructLength> {
		match self {
			Self::Format1(v) => v.struct_length(),
			Self::Format2(v) => v.struct_length(),
			Self::Format3(v) => v.struct_length(),
			Self::Format4(v) => v.struct_length(),
			Self::Format5(v) => v.struct_length(),
			Self::Format6(v) => v.struct_length(),
			Self::Unknown(_) => None,
		}
	}
	fn propagated_counts(&self) -> &'static [&'static str] {
		match self {
			Self::Format1(v) => v.propagated_counts(),
			Self::Format2(v) => v.propagated_counts(),
			Self::Format3(v) => v.propagated_counts(),
			Self::Format4(v) => v.propagated_counts(),
			Self::Format5(v) => v.propagated_counts(),
			Self::Format6(v) => v.propagated_counts(),
			Self::Unknown(_) => &[],
		}
	}
	fn set_propagated_count(&mut self, name: &str, value: Option<u32>) {
		match self {
			Self::Format1(v) => v.set_propagated_count(name, value),
			Self::Format2(v) => v.set_propagated_count(name, value),
			Self::Format3(v) => v.set_propagated_count(name, value),
			Self::Format4(v) => v.set_propagated_count(name, value),
			Self::Format5(v) => v.set_propagated_count(name, value),
			Self::Format6(v) => v.set_propagated_count(name, value),
			Self::Unknown(_) => {}
		}
	}
	fn with_format(format: u16) -> Self {
		match format {
			1 => Self::Format1(ContextSubstFormat1::default()),
			2 => Self::Format2(ContextSubstFormat2::default()),
			3 => Self::Format3(ContextSubstFormat3::default()),
			4 => Self::Format4(ContextSubstFormat4::default()),
			5 => Self::Format5(ContextSubstFormat5::default()),
			6 => Self::Format6(ContextSubstFormat6::default()),
			f => Self::Unknown(f),
		}
	}
}

/// `ContextualMorph`.
