/// `CursivePos` format 2.
#[derive(Debug, Clone, PartialEq)]
pub struct CursivePosFormat2 {
	/// `Coverage` (LTable).
	pub coverage: Option<Box<Coverage>>,
	/// `EntryExitCount` (ComputedUInt24).
	pub entry_exit_count: Option<u32>,
	/// `EntryExitRecord` (Struct).
	pub entry_exit_record: Vec<EntryExit2>,
	/// Whether the subtables below are never shared (`DontShare`), set when
	/// resolving offset overflows.
	pub dont_share: bool,
}

impl Default for CursivePosFormat2 {
	fn default() -> Self {
		CursivePosFormat2 {
			coverage: Default::default(),
			entry_exit_count: Default::default(),
			entry_exit_record: Default::default(),
			dont_share: false,
		}
	}
}

impl OtTable for CursivePosFormat2 {
	fn class_name(&self) -> &'static str {
		"CursivePos"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.coverage = read_offset::<Coverage>(r, font, 4)?;
		t.entry_exit_count = Some(r.read_u24()? as u32);
		{
			let n = repeat_count(t.entry_exit_count.map(|v| v as i64), 0, "EntryExitCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(EntryExit2::decompile(r, font)?);
			}
			t.entry_exit_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if self.dont_share {
			w.set_dont_share();
		}
		w.count_ref("LookupType")?.set_value(3)?;
		w.write_u16(2);
		let t = self;
		let _ = t;
		write_offset(w, font, self.coverage.as_deref(), 4, "Coverage", None)?;
		let count_entry_exit_count = CountRef::new("EntryExitCount", 3, None);
		w.write_count_reference(count_entry_exit_count.clone());
		count_entry_exit_count.set_value((self.entry_exit_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.entry_exit_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn dont_share(&self) -> bool {
		self.dont_share
	}
	fn set_dont_share(&mut self) {
		self.dont_share = true;
	}
	fn format(&self) -> Option<u16> {
		Some(2)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.coverage.as_deref(),
			Some("Coverage"),
			&Attrs::new(),
		)?;
		xml_computed(xw, "EntryExitCount", self.entry_exit_count);
		for (i, item) in self.entry_exit_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("EntryExitRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Coverage" => self.coverage = xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new),
			"EntryExitCount" => self.entry_exit_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"EntryExitRecord" => self
				.entry_exit_record
				.push(xml_read_struct::<EntryExit2>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.entry_exit_count = Some((self.entry_exit_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.coverage;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.entry_exit_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

