/// `ExtenderGlyph`.
#[derive(Debug, Clone, PartialEq)]
pub struct ExtenderGlyph {
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `ExtenderGlyph` (GlyphID).
	pub extender_glyph: Vec<u32>,
}

impl Default for ExtenderGlyph {
	fn default() -> Self {
		ExtenderGlyph {
			glyph_count: Default::default(),
			extender_glyph: Default::default(),
		}
	}
}

impl OtTable for ExtenderGlyph {
	fn class_name(&self) -> &'static str {
		"ExtenderGlyph"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.glyph_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), 0, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()? as u32);
			}
			t.extender_glyph = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		count_glyph_count.set_value((self.extender_glyph.len() as i64 - 0) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.extender_glyph.iter().enumerate() {
				let _ = i;
				write_glyph(w, (*item), 2)?;
			}
			Ok(())
		})?;
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "GlyphCount", self.glyph_count);
		for (i, item) in self.extender_glyph.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "ExtenderGlyph", &attrs, font.glyph_name((*item))?);
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"ExtenderGlyph" => self.extender_glyph.push(font.glyph_id(value_attr(e)?)?),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.glyph_count = Some((self.extender_glyph.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.extender_glyph.iter_mut() {
			*v = f(*v)?;
		}
		Ok(())
	}
}

