/// `ExtensionSubst` format 1.
#[derive(Debug, Clone, PartialEq)]
pub struct ExtensionSubstFormat1 {
	/// `ExtensionLookupType` (UShort).
	pub extension_lookup_type: u16,
	/// `ExtSubTable` (ExtSubTable).
	pub ext_sub_table: Option<Box<LookupSubTable>>,
	/// Whether the subtables below are never shared (`DontShare`), set when
	/// resolving offset overflows.
	pub dont_share: bool,
}

impl Default for ExtensionSubstFormat1 {
	fn default() -> Self {
		ExtensionSubstFormat1 {
			extension_lookup_type: Default::default(),
			ext_sub_table: Default::default(),
			dont_share: false,
		}
	}
}

impl OtTable for ExtensionSubstFormat1 {
	fn class_name(&self) -> &'static str {
		"ExtensionSubst"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.extension_lookup_type = r.read_u16()?;
		t.ext_sub_table = LookupSubTable::read_offset(r, font, 4, t.extension_lookup_type)?;
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if self.dont_share {
			w.set_dont_share();
		}
		w.count_ref("LookupType")?.set_value(7)?;
		w.write_u16(1);
		let t = self;
		let _ = t;
		{
			let lt = CountRef::new(
				"ExtensionLookupType",
				2,
				Some(self.extension_lookup_type as u64),
			);
			w.write_count_reference(lt.clone());
			w.set("LookupType", StateValue::Count(lt));
		}
		w.set_extension();
		write_offset(
			w,
			font,
			self.ext_sub_table.as_deref(),
			4,
			"ExtSubTable",
			None,
		)?;
		Ok(())
	}
	fn dont_share(&self) -> bool {
		self.dont_share
	}
	fn set_dont_share(&mut self) {
		self.dont_share = true;
	}
	fn format(&self) -> Option<u16> {
		Some(1)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(
			xw,
			"ExtensionLookupType",
			&Attrs::new(),
			self.extension_lookup_type.to_string(),
		);
		xml_struct(xw, font, self.ext_sub_table.as_deref(), None, &Attrs::new())?;
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"ExtensionLookupType" => self.extension_lookup_type = parse_int::<u16>(value_attr(e)?)?,
			"AlternateSubst"
			| "ChainContextPos"
			| "ChainContextSubst"
			| "ContextPos"
			| "ContextSubst"
			| "ContextualMorph"
			| "CursivePos"
			| "ExtensionPos"
			| "ExtensionSubst"
			| "InsertionMorph"
			| "LigatureMorph"
			| "LigatureSubst"
			| "MarkBasePos"
			| "MarkLigPos"
			| "MarkMarkPos"
			| "MultipleSubst"
			| "NoncontextualMorph"
			| "PairPos"
			| "RearrangementMorph"
			| "ReverseChainSingleSubst"
			| "SinglePos"
			| "SingleSubst" => {
				self.ext_sub_table = LookupSubTable::xml_read_named(e, font, ctx)?.map(Box::new)
			}
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.ext_sub_table;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

