/// `Feature`.
#[derive(Debug, Clone, PartialEq)]
pub struct Feature {
	/// `FeatureParams` (FeatureParams).
	pub feature_params: Option<Box<FeatureParamsAny>>,
	/// `LookupCount` (ComputedUShort).
	pub lookup_count: Option<u32>,
	/// `LookupListIndex` (UShort).
	pub lookup_list_index: Vec<u16>,
}

impl Default for Feature {
	fn default() -> Self {
		Feature {
			feature_params: Default::default(),
			lookup_count: Default::default(),
			lookup_list_index: Default::default(),
		}
	}
}

impl OtTable for Feature {
	fn class_name(&self) -> &'static str {
		"Feature"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.feature_params = FeatureParamsAny::read_offset(r, font)?;
		t.lookup_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.lookup_count.map(|v| v as i64), 0, "LookupCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.lookup_list_index = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		write_offset(
			w,
			font,
			self.feature_params.as_deref(),
			2,
			"FeatureParams",
			None,
		)?;
		let count_lookup_count = CountRef::new("LookupCount", 2, None);
		w.write_count_reference(count_lookup_count.clone());
		count_lookup_count.set_value((self.lookup_list_index.len() as i64 - 0) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.lookup_list_index.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.feature_params.as_deref(),
			None,
			&Attrs::new(),
		)?;
		xml_computed(xw, "LookupCount", self.lookup_count);
		for (i, item) in self.lookup_list_index.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "LookupListIndex", &attrs, (*item).to_string());
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"FeatureParams"
			| "FeatureParamsCharacterVariants"
			| "FeatureParamsSize"
			| "FeatureParamsStylisticSet" => {
				self.feature_params = FeatureParamsAny::xml_read_named(e, font, ctx)?.map(Box::new)
			}
			"LookupCount" => self.lookup_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"LookupListIndex" => self
				.lookup_list_index
				.push(parse_int::<u16>(value_attr(e)?)?),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.lookup_count = Some((self.lookup_list_index.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.feature_params;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

