/// `FeatureTableSubstitution`.
#[derive(Debug, Clone, PartialEq)]
pub struct FeatureTableSubstitution {
	/// `Version` (Version).
	pub version: u32,
	/// `SubstitutionCount` (ComputedUShort).
	pub substitution_count: Option<u32>,
	/// `SubstitutionRecord` (Struct).
	pub substitution_record: Vec<FeatureTableSubstitutionRecord>,
}

impl Default for FeatureTableSubstitution {
	fn default() -> Self {
		FeatureTableSubstitution {
			version: Default::default(),
			substitution_count: Default::default(),
			substitution_record: Default::default(),
		}
	}
}

impl OtTable for FeatureTableSubstitution {
	fn class_name(&self) -> &'static str {
		"FeatureTableSubstitution"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.version = r.read_u32()?;
		t.substitution_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(
				t.substitution_count.map(|v| v as i64),
				0,
				"SubstitutionCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(FeatureTableSubstitutionRecord::decompile(r, font)?);
			}
			t.substitution_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.write_u32(version_as_long(self.version)?);
		let count_substitution_count = CountRef::new("SubstitutionCount", 2, None);
		w.write_count_reference(count_substitution_count.clone());
		count_substitution_count.set_value((self.substitution_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.substitution_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(
			xw,
			"Version",
			&Attrs::new(),
			format!("0x{:08x}", self.version),
		);
		xml_computed(xw, "SubstitutionCount", self.substitution_count);
		for (i, item) in self.substitution_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("SubstitutionRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Version" => self.version = parse_version(value_attr(e)?)?,
			"SubstitutionCount" => {
				self.substitution_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"SubstitutionRecord" => self.substitution_record.push(
				xml_read_struct::<FeatureTableSubstitutionRecord>(e, font, ctx)?
					.unwrap_or_default(),
			),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.substitution_count = Some((self.substitution_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.substitution_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

