		xml_simple(
			xw,
			"Version",
			&Attrs::new(),
			format!("0x{:08x}", self.version),
		);
		xml_computed(xw, "FeatureVariationCount", self.feature_variation_count);
		for (i, item) in self.feature_variation_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("FeatureVariationRecord"), &attrs)?;
		}
