/// `GlyphProperties` (format-switching).
#[derive(Debug, Clone, PartialEq)]
pub enum GlyphProperties {
	/// Format 0.
	Format0(GlyphPropertiesFormat0),
	/// Format 1.
	Format1(GlyphPropertiesFormat1),
	/// A format fontTools does not know; it has no fields.
	Unknown(u16),
}

impl Default for GlyphProperties {
	fn default() -> Self {
		Self::with_format(0)
	}
}

impl OtTable for GlyphProperties {
	fn class_name(&self) -> &'static str {
		"GlyphProperties"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let format = r.read_u16()?;
		Ok(match format {
			0 => Self::Format0(GlyphPropertiesFormat0::decompile(r, font)?),
			1 => Self::Format1(GlyphPropertiesFormat1::decompile(r, font)?),
			f => Self::Unknown(f),
		})
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		match self {
			Self::Format0(v) => v.compile(w, font),
			Self::Format1(v) => v.compile(w, font),
			Self::Unknown(f) => {
				w.write_u16(*f);
				Ok(())
			}
		}
	}
	fn format(&self) -> Option<u16> {
		Some(match self {
			Self::Format0(_) => 0,
			Self::Format1(_) => 1,
			Self::Unknown(f) => *f,
		})
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		match self {
			Self::Format0(v) => v.to_xml2(xw, font),
			Self::Format1(v) => v.to_xml2(xw, font),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format0(v) => v.from_xml(element, font, ctx),
			Self::Format1(v) => v.from_xml(element, font, ctx),
			Self::Unknown(_) => Err(Error::ttx(format!("KeyError: {:?}", element.name))),
		}
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format0(v) => v.populate_defaults(ctx),
			Self::Format1(v) => v.populate_defaults(ctx),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		match self {
			Self::Format0(v) => v.remap_glyphs(f),
			Self::Format1(v) => v.remap_glyphs(f),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn struct_length(&self) -> Option<StructLength> {
		match self {
			Self::Format0(v) => v.struct_length(),
			Self::Format1(v) => v.struct_length(),
			Self::Unknown(_) => None,
		}
	}
	fn propagated_counts(&self) -> &'static [&'static str] {
		match self {
			Self::Format0(v) => v.propagated_counts(),
			Self::Format1(v) => v.propagated_counts(),
			Self::Unknown(_) => &[],
		}
	}
	fn set_propagated_count(&mut self, name: &str, value: Option<u32>) {
		match self {
			Self::Format0(v) => v.set_propagated_count(name, value),
			Self::Format1(v) => v.set_propagated_count(name, value),
			Self::Unknown(_) => {}
		}
	}
	fn with_format(format: u16) -> Self {
		match format {
			0 => Self::Format0(GlyphPropertiesFormat0::default()),
			1 => Self::Format1(GlyphPropertiesFormat1::default()),
			f => Self::Unknown(f),
		}
	}
}

