impl OtTable for HVAR {
	fn class_name(&self) -> &'static str {
		"HVAR"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.version = r.read_u32()?;
		t.var_store = read_offset::<VarStore>(r, font, 4)?;
		t.adv_width_map = read_offset::<VarIdxMap>(r, font, 4)?;
		t.lsb_map = read_offset::<VarIdxMap>(r, font, 4)?;
		t.rsb_map = read_offset::<VarIdxMap>(r, font, 4)?;
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.write_u32(version_as_long(self.version)?);
		write_offset(w, font, self.var_store.as_deref(), 4, "VarStore", None)?;
		write_offset(
			w,
			font,
			self.adv_width_map.as_deref(),
			4,
			"AdvWidthMap",
			None,
		)?;
		write_offset(w, font, self.lsb_map.as_deref(), 4, "LsbMap", None)?;
		write_offset(w, font, self.rsb_map.as_deref(), 4, "RsbMap", None)?;
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(
			xw,
			"Version",
			&Attrs::new(),
			format!("0x{:08x}", self.version),
		);
		xml_struct(
			xw,
			font,
			self.var_store.as_deref(),
			Some("VarStore"),
			&Attrs::new(),
		)?;
		xml_struct(
			xw,
			font,
			self.adv_width_map.as_deref(),
			Some("AdvWidthMap"),
			&Attrs::new(),
		)?;
		xml_struct(
			xw,
			font,
			self.lsb_map.as_deref(),
			Some("LsbMap"),
			&Attrs::new(),
		)?;
		xml_struct(
			xw,
			font,
			self.rsb_map.as_deref(),
			Some("RsbMap"),
			&Attrs::new(),
		)?;
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Version" => self.version = parse_version(value_attr(e)?)?,
			"VarStore" => self.var_store = xml_read_struct::<VarStore>(e, font, ctx)?.map(Box::new),
			"AdvWidthMap" => {
				self.adv_width_map = xml_read_struct::<VarIdxMap>(e, font, ctx)?.map(Box::new)
			}
			"LsbMap" => self.lsb_map = xml_read_struct::<VarIdxMap>(e, font, ctx)?.map(Box::new),
			"RsbMap" => self.rsb_map = xml_read_struct::<VarIdxMap>(e, font, ctx)?.map(Box::new),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.var_store;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		{
			let v = &mut self.adv_width_map;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		{
			let v = &mut self.lsb_map;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		{
			let v = &mut self.rsb_map;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

