/// `LangSys`.
#[derive(Debug, Clone, PartialEq)]
pub struct LangSys {
	/// `LookupOrder` (Table).
	pub lookup_order: Option<Box<LookupOrder>>,
	/// `ReqFeatureIndex` (UShort).
	pub req_feature_index: u16,
	/// `FeatureCount` (ComputedUShort).
	pub feature_count: Option<u32>,
	/// `FeatureIndex` (UShort).
	pub feature_index: Vec<u16>,
}

impl Default for LangSys {
	fn default() -> Self {
		LangSys {
			lookup_order: Default::default(),
			req_feature_index: Default::default(),
			feature_count: Default::default(),
			feature_index: Default::default(),
		}
	}
}

impl OtTable for LangSys {
	fn class_name(&self) -> &'static str {
		"LangSys"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.lookup_order = read_offset::<LookupOrder>(r, font, 2)?;
		t.req_feature_index = r.read_u16()?;
		t.feature_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.feature_count.map(|v| v as i64), 0, "FeatureCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.feature_index = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		write_offset(
			w,
			font,
			self.lookup_order.as_deref(),
			2,
			"LookupOrder",
			None,
		)?;
		w.write_u16(self.req_feature_index);
		let count_feature_count = CountRef::new("FeatureCount", 2, None);
		w.write_count_reference(count_feature_count.clone());
		count_feature_count.set_value((self.feature_index.len() as i64 - 0) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.feature_index.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.lookup_order.as_deref(),
			Some("LookupOrder"),
			&Attrs::new(),
		)?;
		xml_simple(
			xw,
			"ReqFeatureIndex",
			&Attrs::new(),
			self.req_feature_index.to_string(),
		);
		xml_computed(xw, "FeatureCount", self.feature_count);
		for (i, item) in self.feature_index.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "FeatureIndex", &attrs, (*item).to_string());
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"LookupOrder" => {
				self.lookup_order = xml_read_struct::<LookupOrder>(e, font, ctx)?.map(Box::new)
			}
			"ReqFeatureIndex" => self.req_feature_index = parse_int::<u16>(value_attr(e)?)?,
			"FeatureCount" => self.feature_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"FeatureIndex" => self.feature_index.push(parse_int::<u16>(value_attr(e)?)?),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.feature_count = Some((self.feature_index.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.lookup_order;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

