/// `MVAR`.
#[derive(Debug, Clone, PartialEq)]
pub struct MVAR {
	/// `Version` (Version).
	pub version: u32,
	/// `Reserved` (UShort).
	pub reserved: u16,
	/// `ValueRecordSize` (UShort).
	pub value_record_size: Option<u32>,
	/// `ValueRecordCount` (ComputedUShort).
	pub value_record_count: Option<u32>,
	/// `VarStore` (Table).
	pub var_store: Option<Box<VarStore>>,
	/// `ValueRecord` (Struct).
	pub value_record: Vec<MetricsValueRecord>,
}

impl Default for MVAR {
	fn default() -> Self {
		MVAR {
			version: Default::default(),
			reserved: Default::default(),
			value_record_size: Default::default(),
			value_record_count: Default::default(),
			var_store: Default::default(),
			value_record: Default::default(),
		}
	}
}

impl OtTable for MVAR {
	fn class_name(&self) -> &'static str {
		"MVAR"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.version = r.read_u32()?;
		t.reserved = r.read_u16()?;
		t.value_record_size = Some(r.read_u16()? as u32);
		r.set(
			"ValueRecordSize",
			StateValue::Int(t.value_record_size.unwrap_or(0) as i64),
		);
		t.value_record_count = Some(r.read_u16()? as u32);
		t.var_store = read_offset::<VarStore>(r, font, 2)?;
		{
			let n = repeat_count(
				t.value_record_count.map(|v| v as i64),
				0,
				"ValueRecordCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(MetricsValueRecord::decompile(r, font)?);
			}
			t.value_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.write_u32(version_as_long(self.version)?);
		w.write_u16(self.reserved);
		let count_value_record_size = CountRef::new("ValueRecordSize", 2, None);
		w.write_count_reference(count_value_record_size.clone());
		w.set(
			"ValueRecordSize",
			StateValue::Count(count_value_record_size.clone()),
		);
		let count_value_record_count = CountRef::new("ValueRecordCount", 2, None);
		w.write_count_reference(count_value_record_count.clone());
		write_offset(w, font, self.var_store.as_deref(), 2, "VarStore", None)?;
		count_value_record_count.set_value((self.value_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.value_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(
			xw,
			"Version",
			&Attrs::new(),
			format!("0x{:08x}", self.version),
		);
		xml_simple(xw, "Reserved", &Attrs::new(), self.reserved.to_string());
		xml_simple(
			xw,
			"ValueRecordSize",
			&Attrs::new(),
			self.value_record_size
				.map_or("None".to_owned(), |v| v.to_string()),
		);
		xml_computed(xw, "ValueRecordCount", self.value_record_count);
		xml_struct(
			xw,
			font,
			self.var_store.as_deref(),
			Some("VarStore"),
			&Attrs::new(),
		)?;
		for (i, item) in self.value_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("ValueRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Version" => self.version = parse_version(value_attr(e)?)?,
			"Reserved" => self.reserved = parse_int::<u16>(value_attr(e)?)?,
			"ValueRecordSize" => self.value_record_size = Some(parse_int::<u32>(value_attr(e)?)?),
			"ValueRecordCount" => self.value_record_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"VarStore" => self.var_store = xml_read_struct::<VarStore>(e, font, ctx)?.map(Box::new),
			"ValueRecord" => self
				.value_record
				.push(xml_read_struct::<MetricsValueRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.value_record_count = Some((self.value_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.var_store;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.value_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
	fn propagated_counts(&self) -> &'static [&'static str] {
		&["ValueRecordSize"]
	}
	fn set_propagated_count(&mut self, name: &str, value: Option<u32>) {
		match name {
			"ValueRecordSize" => {
				if value.is_some() {
					self.value_record_size = value;
				}
			}
			_ => {}
		}
	}
}

