/// `MortChain`.
#[derive(Debug, Clone, PartialEq)]
pub struct MortChain {
	/// `DefaultFlags` (Flags32).
	pub default_flags: u32,
	/// `StructLength` (ComputedULong).
	pub struct_length: Option<u32>,
	/// `MorphFeatureCount` (ComputedUShort).
	pub morph_feature_count: Option<u32>,
	/// `MorphSubtableCount` (ComputedUShort).
	pub morph_subtable_count: Option<u32>,
	/// `MorphFeature` (Struct).
	pub morph_feature: Vec<MorphFeature>,
	/// `MorphSubtable` (MortSubtableConverter).
	pub morph_subtable: Vec<MortSubtable>,
}

impl Default for MortChain {
	fn default() -> Self {
		MortChain {
			default_flags: Default::default(),
			struct_length: Default::default(),
			morph_feature_count: Default::default(),
			morph_subtable_count: Default::default(),
			morph_feature: Default::default(),
			morph_subtable: Default::default(),
		}
	}
}

impl OtTable for MortChain {
	fn class_name(&self) -> &'static str {
		"MortChain"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.default_flags = r.read_u32()?;
		t.struct_length = Some(r.read_u32()? as u32);
		t.morph_feature_count = Some(r.read_u16()? as u32);
		t.morph_subtable_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(
				t.morph_feature_count.map(|v| v as i64),
				0,
				"MorphFeatureCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(MorphFeature::decompile(r, font)?);
			}
			t.morph_feature = v;
		}
		{
			let n = repeat_count(
				t.morph_subtable_count.map(|v| v as i64),
				0,
				"MorphSubtableCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_mort_subtable(r, font)?);
			}
			t.morph_subtable = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.write_u32(self.default_flags);
		let count_struct_length = CountRef::new("StructLength", 4, None);
		w.write_count_reference(count_struct_length.clone());
		let count_morph_feature_count = CountRef::new("MorphFeatureCount", 2, None);
		w.write_count_reference(count_morph_feature_count.clone());
		let count_morph_subtable_count = CountRef::new("MorphSubtableCount", 2, None);
		w.write_count_reference(count_morph_subtable_count.clone());
		count_morph_feature_count.set_value((self.morph_feature.len() as i64 - 0) as u64)?;
		for (i, item) in self.morph_feature.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		count_morph_subtable_count.set_value((self.morph_subtable.len() as i64 - 0) as u64)?;
		for (i, item) in self.morph_subtable.iter().enumerate() {
			let _ = i;
			write_mort_subtable(w, font, &(*item))?;
		}
		Ok(())
	}
	fn struct_length(&self) -> Option<StructLength> {
		Some(StructLength {
			value: self.struct_length,
			item: 1,
			size: 4,
		})
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(
			xw,
			"DefaultFlags",
			&Attrs::new(),
			format!("0x{:08X}", self.default_flags),
		);
		xml_computed(xw, "StructLength", self.struct_length);
		xml_computed(xw, "MorphFeatureCount", self.morph_feature_count);
		xml_computed(xw, "MorphSubtableCount", self.morph_subtable_count);
		for (i, item) in self.morph_feature.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("MorphFeature"), &attrs)?;
		}
		for (i, item) in self.morph_subtable.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_mort_subtable(xw, font, "MorphSubtable", &attrs, item)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"DefaultFlags" => self.default_flags = parse_int::<u32>(value_attr(e)?)?,
			"StructLength" => self.struct_length = Some(parse_int::<u32>(value_attr(e)?)?),
			"MorphFeatureCount" => {
				self.morph_feature_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"MorphSubtableCount" => {
				self.morph_subtable_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"MorphFeature" => self
				.morph_feature
				.push(xml_read_struct::<MorphFeature>(e, font, ctx)?.unwrap_or_default()),
			"MorphSubtable" => self.morph_subtable.push(read_mort_subtable_xml(e, font)?),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.morph_feature_count = Some((self.morph_feature.len() as i64 - 0).max(0) as u32);
		self.morph_subtable_count = Some((self.morph_subtable.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.morph_feature.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		for v in self.morph_subtable.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

