/// `MultiVarData`.
#[derive(Debug, Clone, PartialEq)]
pub struct MultiVarData {
	/// `Format` (UInt8).
	pub format: u8,
	/// `VarRegionCount` (ComputedUShort).
	pub var_region_count: Option<u32>,
	/// `VarRegionIndex` (UShort).
	pub var_region_index: Vec<u16>,
	/// `Item` (TupleListOffset).
	pub item: Vec<Vec<i64>>,
}

impl Default for MultiVarData {
	fn default() -> Self {
		MultiVarData {
			format: Default::default(),
			var_region_count: Default::default(),
			var_region_index: Default::default(),
			item: Default::default(),
		}
	}
}

impl OtTable for MultiVarData {
	fn class_name(&self) -> &'static str {
		"MultiVarData"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.format = r.read_u8()?;
		t.var_region_count = Some(r.read_u16()? as u32);
		r.set(
			"VarRegionCount",
			StateValue::Int(t.var_region_count.unwrap_or(0) as i64),
		);
		{
			let n = repeat_count(t.var_region_count.map(|v| v as i64), 0, "VarRegionCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.var_region_index = v;
		}
		t.item = read_tuple_list_offset(r)?;
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.write_u8(self.format);
		let count_var_region_count = CountRef::new("VarRegionCount", 2, None);
		w.write_count_reference(count_var_region_count.clone());
		w.set(
			"VarRegionCount",
			StateValue::Count(count_var_region_count.clone()),
		);
		count_var_region_count.set_value((self.var_region_index.len() as i64 - 0) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.var_region_index.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		write_tuple_list_offset(w, &self.item, "Item")?;
		Ok(())
	}
	fn format(&self) -> Option<u16> {
		Some(self.format as u16)
	}
	fn with_format(format: u16) -> Self {
		Self {
			format: format as _,
			..Self::default()
		}
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(xw, "Format", &Attrs::new(), self.format.to_string());
		xml_computed(xw, "VarRegionCount", self.var_region_count);
		for (i, item) in self.var_region_index.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "VarRegionIndex", &attrs, (*item).to_string());
		}
		xml_tuple_list(xw, "Item", &Attrs::new(), &self.item);
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Format" => self.format = parse_int::<u8>(value_attr(e)?)?,
			"VarRegionCount" => self.var_region_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"VarRegionIndex" => self
				.var_region_index
				.push(parse_int::<u16>(value_attr(e)?)?),
			"Item" => self.item.push(parse_tuple(e)?),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.var_region_count = Some((self.var_region_index.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		let _ = f;
		Ok(())
	}
	fn propagated_counts(&self) -> &'static [&'static str] {
		&["VarRegionCount"]
	}
	fn set_propagated_count(&mut self, name: &str, value: Option<u32>) {
		match name {
			"VarRegionCount" => {
				if value.is_some() {
					self.var_region_count = value;
				}
			}
			_ => {}
		}
	}
}

