/// `PairPos` format 1.
#[derive(Debug, Clone, PartialEq)]
pub struct PairPosFormat1 {
	/// `Coverage` (Table).
	pub coverage: Option<Box<Coverage>>,
	/// `ValueFormat1` (ValueFormat).
	pub value_format1: u16,
	/// `ValueFormat2` (ValueFormat).
	pub value_format2: u16,
	/// `PairSetCount` (ComputedUShort).
	pub pair_set_count: Option<u32>,
	/// `PairSet` (Table).
	pub pair_set: Vec<Option<Box<PairSet>>>,
	/// Whether the subtables below are never shared (`DontShare`), set when
	/// resolving offset overflows.
	pub dont_share: bool,
}

impl Default for PairPosFormat1 {
	fn default() -> Self {
		PairPosFormat1 {
			coverage: Default::default(),
			value_format1: Default::default(),
			value_format2: Default::default(),
			pair_set_count: Default::default(),
			pair_set: Default::default(),
			dont_share: false,
		}
	}
}

impl OtTable for PairPosFormat1 {
	fn class_name(&self) -> &'static str {
		"PairPos"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.coverage = read_offset::<Coverage>(r, font, 2)?;
		t.value_format1 = {
			let v = r.read_u16()?;
			r.set("ValueFormat1", StateValue::ValueFormat(v));
			v
		};
		t.value_format2 = {
			let v = r.read_u16()?;
			r.set("ValueFormat2", StateValue::ValueFormat(v));
			v
		};
		t.pair_set_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.pair_set_count.map(|v| v as i64), 0, "PairSetCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<PairSet>(r, font, 2)?);
			}
			t.pair_set = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if self.dont_share {
			w.set_dont_share();
		}
		w.count_ref("LookupType")?.set_value(2)?;
		w.write_u16(1);
		let t = self;
		let _ = t;
		write_offset(w, font, self.coverage.as_deref(), 2, "Coverage", None)?;
		w.write_u16(self.value_format1);
		w.set("ValueFormat1", StateValue::ValueFormat(self.value_format1));
		w.write_u16(self.value_format2);
		w.set("ValueFormat2", StateValue::ValueFormat(self.value_format2));
		let count_pair_set_count = CountRef::new("PairSetCount", 2, None);
		w.write_count_reference(count_pair_set_count.clone());
		count_pair_set_count.set_value((self.pair_set.len() as i64 - 0) as u64)?;
		for (i, item) in self.pair_set.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 2, "PairSet", Some(i))?;
		}
		Ok(())
	}
	fn dont_share(&self) -> bool {
		self.dont_share
	}
	fn set_dont_share(&mut self) {
		self.dont_share = true;
	}
	fn format(&self) -> Option<u16> {
		Some(1)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.coverage.as_deref(),
			Some("Coverage"),
			&Attrs::new(),
		)?;
		xml_simple(
			xw,
			"ValueFormat1",
			&Attrs::new(),
			self.value_format1.to_string(),
		);
		xml_simple(
			xw,
			"ValueFormat2",
			&Attrs::new(),
			self.value_format2.to_string(),
		);
		xml_computed(xw, "PairSetCount", self.pair_set_count);
		for (i, item) in self.pair_set.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("PairSet"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Coverage" => self.coverage = xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new),
			"ValueFormat1" => self.value_format1 = parse_int::<u16>(value_attr(e)?)?,
			"ValueFormat2" => self.value_format2 = parse_int::<u16>(value_attr(e)?)?,
			"PairSetCount" => self.pair_set_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"PairSet" => self
				.pair_set
				.push(xml_read_struct::<PairSet>(e, font, ctx)?.map(Box::new)),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.pair_set_count = Some((self.pair_set.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.coverage;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.pair_set.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

