/// `PatchMap` format 2.
#[derive(Debug, Clone, PartialEq)]
pub struct PatchMapFormat2 {
	/// `Reserved` (UInt24).
	pub reserved: u32,
	/// `Flags` (UInt8).
	pub flags: u8,
	/// `CompatibilityId` (ULong).
	pub compatibility_id: Vec<u32>,
	/// `DefaultPatchFormat` (UInt8).
	pub default_patch_format: u8,
	/// `NumEntries` (UInt24).
	pub num_entries: u32,
	/// `MappingEntries` (LTable).
	pub mapping_entries: Option<Box<MappingEntries>>,
	/// `EntryIdStringData` (LTable).
	pub entry_id_string_data: Option<Box<EntryIdStringData>>,
	/// `UrlTemplateLength` (UShort).
	pub url_template_length: u16,
	/// `UrlTemplate` (UInt8).
	pub url_template: Vec<u8>,
	/// `CffCharStringsOffset` (ULong).
	pub cff_char_strings_offset: u32,
	/// `Cff2CharStringsOffset` (ULong).
	pub cff2_char_strings_offset: u32,
}

impl Default for PatchMapFormat2 {
	fn default() -> Self {
		PatchMapFormat2 {
			reserved: Default::default(),
			flags: Default::default(),
			compatibility_id: Default::default(),
			default_patch_format: Default::default(),
			num_entries: Default::default(),
			mapping_entries: Default::default(),
			entry_id_string_data: Default::default(),
			url_template_length: Default::default(),
			url_template: Default::default(),
			cff_char_strings_offset: Default::default(),
			cff2_char_strings_offset: Default::default(),
		}
	}
}

impl OtTable for PatchMapFormat2 {
	fn class_name(&self) -> &'static str {
		"PatchMap"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.reserved = r.read_u24()?;
		t.flags = r.read_u8()?;
		{
			let n = 4usize;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u32()?);
			}
			t.compatibility_id = v;
		}
		t.default_patch_format = r.read_u8()?;
		t.num_entries = r.read_u24()?;
		r.set("NumEntries", StateValue::Int(t.num_entries as i64));
		t.mapping_entries = read_offset::<MappingEntries>(r, font, 4)?;
		t.entry_id_string_data = read_offset::<EntryIdStringData>(r, font, 4)?;
		t.url_template_length = r.read_u16()?;
		{
			let n = repeat_count(Some(t.url_template_length as i64), 0, "UrlTemplateLength")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u8()?);
			}
			t.url_template = v;
		}
		if (t.flags as i64) & 0x01 != 0 {
			t.cff_char_strings_offset = r.read_u32()?;
		}
		if (t.flags as i64) & 0x02 != 0 {
			t.cff2_char_strings_offset = r.read_u32()?;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		w.write_u8(2);
		let t = self;
		let _ = t;
		w.write_u24(self.reserved)?;
		w.write_u8(self.flags);
		if self.compatibility_id.len() as i64 != 4 {
			return Err(Error::Assertion(format!(
				"expected 4 values, got {}",
				self.compatibility_id.len()
			)));
		}
		w.write_array(|w| {
			for (i, item) in self.compatibility_id.iter().enumerate() {
				let _ = i;
				w.write_u32((*item));
			}
			Ok(())
		})?;
		w.write_u8(self.default_patch_format);
		w.write_u24(self.num_entries)?;
		w.set("NumEntries", StateValue::Int(self.num_entries as i64));
		write_offset(
			w,
			font,
			self.mapping_entries.as_deref(),
			4,
			"MappingEntries",
			None,
		)?;
		write_offset(
			w,
			font,
			self.entry_id_string_data.as_deref(),
			4,
			"EntryIdStringData",
			None,
		)?;
		w.write_u16(self.url_template_length);
		if self.url_template_length as i64 != self.url_template.len() as i64 - 0 {
			return Err(Error::Assertion(format!(
				"(UrlTemplateLength, {}, {})",
				self.url_template_length,
				self.url_template.len() as i64 - 0
			)));
		}
		w.write_array(|w| {
			for (i, item) in self.url_template.iter().enumerate() {
				let _ = i;
				w.write_u8((*item));
			}
			Ok(())
		})?;
		if (t.flags as i64) & 0x01 != 0 {
			w.write_u32(self.cff_char_strings_offset);
		}
		if (t.flags as i64) & 0x02 != 0 {
			w.write_u32(self.cff2_char_strings_offset);
		}
		Ok(())
	}
	fn format(&self) -> Option<u16> {
		Some(2)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(xw, "Reserved", &Attrs::new(), self.reserved.to_string());
		xml_simple(xw, "Flags", &Attrs::new(), self.flags.to_string());
		for (i, item) in self.compatibility_id.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "CompatibilityId", &attrs, (*item).to_string());
		}
		xml_simple(
			xw,
			"DefaultPatchFormat",
			&Attrs::new(),
			self.default_patch_format.to_string(),
		);
		xml_simple(
			xw,
			"NumEntries",
			&Attrs::new(),
			self.num_entries.to_string(),
		);
		xml_struct(
			xw,
			font,
			self.mapping_entries.as_deref(),
			Some("MappingEntries"),
			&Attrs::new(),
		)?;
		xml_struct(
			xw,
			font,
			self.entry_id_string_data.as_deref(),
			Some("EntryIdStringData"),
			&Attrs::new(),
		)?;
		xml_simple(
			xw,
			"UrlTemplateLength",
			&Attrs::new(),
			self.url_template_length.to_string(),
		);
		for (i, item) in self.url_template.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "UrlTemplate", &attrs, (*item).to_string());
		}
		if (t.flags as i64) & 0x01 != 0 {
			xml_simple(
				xw,
				"CffCharStringsOffset",
				&Attrs::new(),
				self.cff_char_strings_offset.to_string(),
			);
		}
		if (t.flags as i64) & 0x02 != 0 {
			xml_simple(
				xw,
				"Cff2CharStringsOffset",
				&Attrs::new(),
				self.cff2_char_strings_offset.to_string(),
			);
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Reserved" => self.reserved = parse_int::<u32>(value_attr(e)?)?,
			"Flags" => self.flags = parse_int::<u8>(value_attr(e)?)?,
			"CompatibilityId" => self
				.compatibility_id
				.push(parse_int::<u32>(value_attr(e)?)?),
			"DefaultPatchFormat" => self.default_patch_format = parse_int::<u8>(value_attr(e)?)?,
			"NumEntries" => self.num_entries = parse_int::<u32>(value_attr(e)?)?,
			"MappingEntries" => {
				self.mapping_entries =
					xml_read_struct::<MappingEntries>(e, font, ctx)?.map(Box::new)
			}
			"EntryIdStringData" => {
				self.entry_id_string_data =
					xml_read_struct::<EntryIdStringData>(e, font, ctx)?.map(Box::new)
			}
			"UrlTemplateLength" => self.url_template_length = parse_int::<u16>(value_attr(e)?)?,
			"UrlTemplate" => self.url_template.push(parse_int::<u8>(value_attr(e)?)?),
			"CffCharStringsOffset" => {
				self.cff_char_strings_offset = parse_int::<u32>(value_attr(e)?)?
			}
			"Cff2CharStringsOffset" => {
				self.cff2_char_strings_offset = parse_int::<u32>(value_attr(e)?)?
			}
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.url_template_length = fit(
			(self.url_template.len() as i64 - 0).max(0) as u64,
			"UrlTemplateLength",
		)?;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.mapping_entries;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		{
			let v = &mut self.entry_id_string_data;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

/// `PatchMap` (format-switching).
#[derive(Debug, Clone, PartialEq)]
pub enum PatchMap {
	/// Format 2.
	Format2(PatchMapFormat2),
	/// A format fontTools does not know; it has no fields.
	Unknown(u16),
}

impl Default for PatchMap {
	fn default() -> Self {
		Self::with_format(2)
	}
}

impl OtTable for PatchMap {
	fn class_name(&self) -> &'static str {
		"PatchMap"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let format = r.read_u8()? as u16;
		Ok(match format {
			2 => Self::Format2(PatchMapFormat2::decompile(r, font)?),
			f => Self::Unknown(f),
		})
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		match self {
			Self::Format2(v) => v.compile(w, font),
			Self::Unknown(f) => {
				w.write_u8(*f as u8);
				Ok(())
			}
		}
	}
	fn format(&self) -> Option<u16> {
		Some(match self {
			Self::Format2(_) => 2,
			Self::Unknown(f) => *f,
		})
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		match self {
			Self::Format2(v) => v.to_xml2(xw, font),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format2(v) => v.from_xml(element, font, ctx),
			Self::Unknown(_) => Err(Error::ttx(format!("KeyError: {:?}", element.name))),
		}
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		match self {
			Self::Format2(v) => v.populate_defaults(ctx),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		match self {
			Self::Format2(v) => v.remap_glyphs(f),
			Self::Unknown(_) => Ok(()),
		}
	}
	fn struct_length(&self) -> Option<StructLength> {
		match self {
			Self::Format2(v) => v.struct_length(),
			Self::Unknown(_) => None,
		}
	}
	fn propagated_counts(&self) -> &'static [&'static str] {
		match self {
			Self::Format2(v) => v.propagated_counts(),
			Self::Unknown(_) => &[],
		}
	}
	fn set_propagated_count(&mut self, name: &str, value: Option<u32>) {
		match self {
			Self::Format2(v) => v.set_propagated_count(name, value),
			Self::Unknown(_) => {}
		}
	}
	fn with_format(format: u16) -> Self {
		match format {
			2 => Self::Format2(PatchMapFormat2::default()),
			f => Self::Unknown(f),
		}
	}
}

/// `PosClassRule`.
#[derive(Debug, Clone, PartialEq)]
pub struct PosClassRule {
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `PosCount` (ComputedUShort).
	pub pos_count: Option<u32>,
	/// `Class` (UShort).
	pub class: Vec<u16>,
	/// `PosLookupRecord` (Struct).
	pub pos_lookup_record: Vec<PosLookupRecord>,
}

impl Default for PosClassRule {
	fn default() -> Self {
		PosClassRule {
			glyph_count: Default::default(),
			pos_count: Default::default(),
			class: Default::default(),
			pos_lookup_record: Default::default(),
		}
	}
}

impl OtTable for PosClassRule {
	fn class_name(&self) -> &'static str {
		"PosClassRule"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.glyph_count = Some(r.read_u16()? as u32);
		t.pos_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), -1, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.class = v;
		}
		{
			let n = repeat_count(t.pos_count.map(|v| v as i64), 0, "PosCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(PosLookupRecord::decompile(r, font)?);
			}
			t.pos_lookup_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		let count_pos_count = CountRef::new("PosCount", 2, None);
		w.write_count_reference(count_pos_count.clone());
		count_glyph_count.set_value((self.class.len() as i64 - -1) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.class.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		count_pos_count.set_value((self.pos_lookup_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.pos_lookup_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "GlyphCount", self.glyph_count);
		xml_computed(xw, "PosCount", self.pos_count);
		for (i, item) in self.class.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "Class", &attrs, (*item).to_string());
		}
		for (i, item) in self.pos_lookup_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("PosLookupRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"PosCount" => self.pos_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"Class" => self.class.push(parse_int::<u16>(value_attr(e)?)?),
			"PosLookupRecord" => self
				.pos_lookup_record
				.push(xml_read_struct::<PosLookupRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.glyph_count = Some((self.class.len() as i64 - -1).max(0) as u32);
		self.pos_count = Some((self.pos_lookup_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.pos_lookup_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

