/// `ReverseChainSingleSubst` format 1.
#[derive(Debug, Clone, PartialEq)]
pub struct ReverseChainSingleSubstFormat1 {
	/// `Coverage` (Table).
	pub coverage: Option<Box<Coverage>>,
	/// `BacktrackGlyphCount` (ComputedUShort).
	pub backtrack_glyph_count: Option<u32>,
	/// `BacktrackCoverage` (Table).
	pub backtrack_coverage: Vec<Option<Box<Coverage>>>,
	/// `LookAheadGlyphCount` (ComputedUShort).
	pub look_ahead_glyph_count: Option<u32>,
	/// `LookAheadCoverage` (Table).
	pub look_ahead_coverage: Vec<Option<Box<Coverage>>>,
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `Substitute` (GlyphID).
	pub substitute: Vec<u32>,
	/// Whether the subtables below are never shared (`DontShare`), set when
	/// resolving offset overflows.
	pub dont_share: bool,
}

impl Default for ReverseChainSingleSubstFormat1 {
	fn default() -> Self {
		ReverseChainSingleSubstFormat1 {
			coverage: Default::default(),
			backtrack_glyph_count: Default::default(),
			backtrack_coverage: Default::default(),
			look_ahead_glyph_count: Default::default(),
			look_ahead_coverage: Default::default(),
			glyph_count: Default::default(),
			substitute: Default::default(),
			dont_share: false,
		}
	}
}

impl OtTable for ReverseChainSingleSubstFormat1 {
	fn class_name(&self) -> &'static str {
		"ReverseChainSingleSubst"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.coverage = read_offset::<Coverage>(r, font, 2)?;
		t.backtrack_glyph_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(
				t.backtrack_glyph_count.map(|v| v as i64),
				0,
				"BacktrackGlyphCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<Coverage>(r, font, 2)?);
			}
			t.backtrack_coverage = v;
		}
		t.look_ahead_glyph_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(
				t.look_ahead_glyph_count.map(|v| v as i64),
				0,
				"LookAheadGlyphCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<Coverage>(r, font, 2)?);
			}
			t.look_ahead_coverage = v;
		}
		t.glyph_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), 0, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()? as u32);
			}
			t.substitute = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		if self.dont_share {
			w.set_dont_share();
		}
		w.count_ref("LookupType")?.set_value(8)?;
		w.write_u16(1);
		let t = self;
		let _ = t;
		write_offset(w, font, self.coverage.as_deref(), 2, "Coverage", None)?;
		let count_backtrack_glyph_count = CountRef::new("BacktrackGlyphCount", 2, None);
		w.write_count_reference(count_backtrack_glyph_count.clone());
		count_backtrack_glyph_count.set_value((self.backtrack_coverage.len() as i64 - 0) as u64)?;
		for (i, item) in self.backtrack_coverage.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 2, "BacktrackCoverage", Some(i))?;
		}
		let count_look_ahead_glyph_count = CountRef::new("LookAheadGlyphCount", 2, None);
		w.write_count_reference(count_look_ahead_glyph_count.clone());
		count_look_ahead_glyph_count
			.set_value((self.look_ahead_coverage.len() as i64 - 0) as u64)?;
		for (i, item) in self.look_ahead_coverage.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 2, "LookAheadCoverage", Some(i))?;
		}
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		count_glyph_count.set_value((self.substitute.len() as i64 - 0) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.substitute.iter().enumerate() {
				let _ = i;
				write_glyph(w, (*item), 2)?;
			}
			Ok(())
		})?;
		Ok(())
	}
	fn dont_share(&self) -> bool {
		self.dont_share
	}
	fn set_dont_share(&mut self) {
		self.dont_share = true;
	}
	fn format(&self) -> Option<u16> {
		Some(1)
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.coverage.as_deref(),
			Some("Coverage"),
			&Attrs::new(),
		)?;
		xml_computed(xw, "BacktrackGlyphCount", self.backtrack_glyph_count);
		for (i, item) in self.backtrack_coverage.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("BacktrackCoverage"), &attrs)?;
		}
		xml_computed(xw, "LookAheadGlyphCount", self.look_ahead_glyph_count);
		for (i, item) in self.look_ahead_coverage.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("LookAheadCoverage"), &attrs)?;
		}
		xml_computed(xw, "GlyphCount", self.glyph_count);
		for (i, item) in self.substitute.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "Substitute", &attrs, font.glyph_name((*item))?);
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Coverage" => self.coverage = xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new),
			"BacktrackGlyphCount" => {
				self.backtrack_glyph_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"BacktrackCoverage" => self
				.backtrack_coverage
				.push(xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new)),
			"LookAheadGlyphCount" => {
				self.look_ahead_glyph_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"LookAheadCoverage" => self
				.look_ahead_coverage
				.push(xml_read_struct::<Coverage>(e, font, ctx)?.map(Box::new)),
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"Substitute" => self.substitute.push(font.glyph_id(value_attr(e)?)?),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.backtrack_glyph_count = Some((self.backtrack_coverage.len() as i64 - 0).max(0) as u32);
		self.look_ahead_glyph_count =
			Some((self.look_ahead_coverage.len() as i64 - 0).max(0) as u32);
		self.glyph_count = Some((self.substitute.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.coverage;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.backtrack_coverage.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.look_ahead_coverage.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.substitute.iter_mut() {
			*v = f(*v)?;
		}
		Ok(())
	}
}

