impl OtTable for STAT {
	fn class_name(&self) -> &'static str {
		"STAT"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.version = r.read_u32()?;
		t.design_axis_record_size = Some(r.read_u16()? as u32);
		r.set(
			"DesignAxisRecordSize",
			StateValue::Int(t.design_axis_record_size.unwrap_or(0) as i64),
		);
		t.design_axis_count = Some(r.read_u16()? as u32);
		r.set(
			"DesignAxisCount",
			StateValue::Int(t.design_axis_count.unwrap_or(0) as i64),
		);
		t.design_axis_record = read_offset::<AxisRecordArray>(r, font, 4)?;
		t.axis_value_count = Some(r.read_u16()? as u32);
		r.set(
			"AxisValueCount",
			StateValue::Int(t.axis_value_count.unwrap_or(0) as i64),
		);
		t.axis_value_array = read_offset::<AxisValueArray>(r, font, 4)?;
		if (t.version as i64) >= 0x00010001 {
			t.elided_fallback_name_id = r.read_u16()?;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.write_u32(version_as_long(self.version)?);
		let count_design_axis_record_size = CountRef::new("DesignAxisRecordSize", 2, None);
		w.write_count_reference(count_design_axis_record_size.clone());
		w.set(
			"DesignAxisRecordSize",
			StateValue::Count(count_design_axis_record_size.clone()),
		);
		let count_design_axis_count = CountRef::new("DesignAxisCount", 2, None);
		w.write_count_reference(count_design_axis_count.clone());
		w.set(
			"DesignAxisCount",
			StateValue::Count(count_design_axis_count.clone()),
		);
		write_offset(
			w,
			font,
			self.design_axis_record.as_deref(),
			4,
			"DesignAxisRecord",
			None,
		)?;
		let count_axis_value_count = CountRef::new("AxisValueCount", 2, None);
		w.write_count_reference(count_axis_value_count.clone());
		w.set(
			"AxisValueCount",
			StateValue::Count(count_axis_value_count.clone()),
		);
		write_offset(
			w,
			font,
			self.axis_value_array.as_deref(),
			4,
			"AxisValueArray",
			None,
		)?;
		if (t.version as i64) >= 0x00010001 {
			w.write_u16(self.elided_fallback_name_id);
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(
			xw,
			"Version",
			&Attrs::new(),
			format!("0x{:08x}", self.version),
		);
		xml_simple(
			xw,
			"DesignAxisRecordSize",
			&Attrs::new(),
			self.design_axis_record_size
				.map_or("None".to_owned(), |v| v.to_string()),
		);
		xml_computed(xw, "DesignAxisCount", self.design_axis_count);
		xml_struct(
			xw,
			font,
			self.design_axis_record.as_deref(),
			Some("DesignAxisRecord"),
			&Attrs::new(),
		)?;
		xml_computed(xw, "AxisValueCount", self.axis_value_count);
		xml_struct(
			xw,
			font,
			self.axis_value_array.as_deref(),
			Some("AxisValueArray"),
			&Attrs::new(),
		)?;
		if (t.version as i64) >= 0x00010001 {
			xml_name_id(
				xw,
				font,
				"ElidedFallbackNameID",
				&Attrs::new(),
				self.elided_fallback_name_id,
			)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Version" => self.version = parse_version(value_attr(e)?)?,
			"DesignAxisRecordSize" => {
				self.design_axis_record_size = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"DesignAxisCount" => self.design_axis_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"DesignAxisRecord" => {
				self.design_axis_record =
					xml_read_struct::<AxisRecordArray>(e, font, ctx)?.map(Box::new)
			}
			"AxisValueCount" => self.axis_value_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"AxisValueArray" => {
				self.axis_value_array =
					xml_read_struct::<AxisValueArray>(e, font, ctx)?.map(Box::new)
			}
			"ElidedFallbackNameID" => {
				self.elided_fallback_name_id = parse_int::<u16>(value_attr(e)?)?
			}
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.design_axis_record;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		{
			let v = &mut self.axis_value_array;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
	fn propagated_counts(&self) -> &'static [&'static str] {
		&["DesignAxisRecordSize", "DesignAxisCount", "AxisValueCount"]
	}
	fn set_propagated_count(&mut self, name: &str, value: Option<u32>) {
		match name {
			"DesignAxisRecordSize" => {
				if value.is_some() {
					self.design_axis_record_size = value;
				}
			}
			"DesignAxisCount" => {
				if value.is_some() {
					self.design_axis_count = value;
				}
			}
			"AxisValueCount" => {
				if value.is_some() {
					self.axis_value_count = value;
				}
			}
			_ => {}
		}
	}
}

/// `Script`.
#[derive(Debug, Clone, PartialEq)]
pub struct Script {
	/// `DefaultLangSys` (Table).
	pub default_lang_sys: Option<Box<LangSys>>,
	/// `LangSysCount` (ComputedUShort).
	pub lang_sys_count: Option<u32>,
	/// `LangSysRecord` (Struct).
	pub lang_sys_record: Vec<LangSysRecord>,
}

impl Default for Script {
	fn default() -> Self {
		Script {
			default_lang_sys: Default::default(),
			lang_sys_count: Default::default(),
			lang_sys_record: Default::default(),
		}
	}
}

impl OtTable for Script {
	fn class_name(&self) -> &'static str {
		"Script"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.default_lang_sys = read_offset::<LangSys>(r, font, 2)?;
		t.lang_sys_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.lang_sys_count.map(|v| v as i64), 0, "LangSysCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(LangSysRecord::decompile(r, font)?);
			}
			t.lang_sys_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		write_offset(
			w,
			font,
			self.default_lang_sys.as_deref(),
			2,
			"DefaultLangSys",
			None,
		)?;
		let count_lang_sys_count = CountRef::new("LangSysCount", 2, None);
		w.write_count_reference(count_lang_sys_count.clone());
		count_lang_sys_count.set_value((self.lang_sys_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.lang_sys_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_struct(
			xw,
			font,
			self.default_lang_sys.as_deref(),
			Some("DefaultLangSys"),
			&Attrs::new(),
		)?;
		xml_computed(xw, "LangSysCount", self.lang_sys_count);
		for (i, item) in self.lang_sys_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("LangSysRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"DefaultLangSys" => {
				self.default_lang_sys = xml_read_struct::<LangSys>(e, font, ctx)?.map(Box::new)
			}
			"LangSysCount" => self.lang_sys_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"LangSysRecord" => self
				.lang_sys_record
				.push(xml_read_struct::<LangSysRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.lang_sys_count = Some((self.lang_sys_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		{
			let v = &mut self.default_lang_sys;
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		for v in self.lang_sys_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

