	fn class_name(&self) -> &'static str {
		"ScriptRecord"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.script_tag = r.read_tag()?;
		t.script = read_offset::<Script>(r, font, 2)?;
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.write_tag(self.script_tag);
		write_offset(w, font, self.script.as_deref(), 2, "Script", None)?;
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_simple(xw, "ScriptTag", &Attrs::new(), self.script_tag.to_string());
		xml_struct(
			xw,
			font,
			self.script.as_deref(),
			Some("Script"),
			&Attrs::new(),
		)?;
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"ScriptTag" => self.script_tag = parse_tag(value_attr(e)?)?,
			"Script" => self.script = xml_read_struct::<Script>(e, font, ctx)?.map(Box::new),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
