/// `Settings`.
#[derive(Debug, Clone, PartialEq)]
pub struct Settings {
	/// `Setting` (Struct).
	pub setting: Vec<Setting>,
}

impl Default for Settings {
	fn default() -> Self {
		Settings {
			setting: Default::default(),
		}
	}
}

impl OtTable for Settings {
	fn class_name(&self) -> &'static str {
		"Settings"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		{
			let n = repeat_count(
				r.get("SettingsCount").and_then(StateValue::as_int),
				0,
				"SettingsCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(Setting::decompile(r, font)?);
			}
			t.setting = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		w.count_ref("SettingsCount")?
			.set_value((self.setting.len() as i64 - 0) as u64)?;
		for (i, item) in self.setting.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		for (i, item) in self.setting.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("Setting"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"Setting" => self
				.setting
				.push(xml_read_struct::<Setting>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		ctx.set_count(
			"SettingsCount",
			(self.setting.len() as i64 - 0).max(0) as u32,
		)?;
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.setting.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

