/// `SubClassRule`.
#[derive(Debug, Clone, PartialEq)]
pub struct SubClassRule {
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `SubstCount` (ComputedUShort).
	pub subst_count: Option<u32>,
	/// `Class` (UShort).
	pub class: Vec<u16>,
	/// `SubstLookupRecord` (Struct).
	pub subst_lookup_record: Vec<SubstLookupRecord>,
}

impl Default for SubClassRule {
	fn default() -> Self {
		SubClassRule {
			glyph_count: Default::default(),
			subst_count: Default::default(),
			class: Default::default(),
			subst_lookup_record: Default::default(),
		}
	}
}

impl OtTable for SubClassRule {
	fn class_name(&self) -> &'static str {
		"SubClassRule"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.glyph_count = Some(r.read_u16()? as u32);
		t.subst_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), -1, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()?);
			}
			t.class = v;
		}
		{
			let n = repeat_count(t.subst_count.map(|v| v as i64), 0, "SubstCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(SubstLookupRecord::decompile(r, font)?);
			}
			t.subst_lookup_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		let count_subst_count = CountRef::new("SubstCount", 2, None);
		w.write_count_reference(count_subst_count.clone());
		count_glyph_count.set_value((self.class.len() as i64 - -1) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.class.iter().enumerate() {
				let _ = i;
				w.write_u16((*item));
			}
			Ok(())
		})?;
		count_subst_count.set_value((self.subst_lookup_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.subst_lookup_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "GlyphCount", self.glyph_count);
		xml_computed(xw, "SubstCount", self.subst_count);
		for (i, item) in self.class.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "Class", &attrs, (*item).to_string());
		}
		for (i, item) in self.subst_lookup_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("SubstLookupRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"SubstCount" => self.subst_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"Class" => self.class.push(parse_int::<u16>(value_attr(e)?)?),
			"SubstLookupRecord" => self
				.subst_lookup_record
				.push(xml_read_struct::<SubstLookupRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.glyph_count = Some((self.class.len() as i64 - -1).max(0) as u32);
		self.subst_count = Some((self.subst_lookup_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.subst_lookup_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

/// `SubClassSet`.
#[derive(Debug, Clone, PartialEq)]
pub struct SubClassSet {
	/// `SubClassRuleCount` (ComputedUShort).
	pub sub_class_rule_count: Option<u32>,
	/// `SubClassRule` (Table).
	pub sub_class_rule: Vec<Option<Box<SubClassRule>>>,
}

impl Default for SubClassSet {
	fn default() -> Self {
		SubClassSet {
			sub_class_rule_count: Default::default(),
			sub_class_rule: Default::default(),
		}
	}
}

impl OtTable for SubClassSet {
	fn class_name(&self) -> &'static str {
		"SubClassSet"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.sub_class_rule_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(
				t.sub_class_rule_count.map(|v| v as i64),
				0,
				"SubClassRuleCount",
			)?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(read_offset::<SubClassRule>(r, font, 2)?);
			}
			t.sub_class_rule = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_sub_class_rule_count = CountRef::new("SubClassRuleCount", 2, None);
		w.write_count_reference(count_sub_class_rule_count.clone());
		count_sub_class_rule_count.set_value((self.sub_class_rule.len() as i64 - 0) as u64)?;
		for (i, item) in self.sub_class_rule.iter().enumerate() {
			let _ = i;
			write_offset(w, font, item.as_deref(), 2, "SubClassRule", Some(i))?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "SubClassRuleCount", self.sub_class_rule_count);
		for (i, item) in self.sub_class_rule.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, item.as_deref(), Some("SubClassRule"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"SubClassRuleCount" => {
				self.sub_class_rule_count = Some(parse_int::<u32>(value_attr(e)?)?)
			}
			"SubClassRule" => self
				.sub_class_rule
				.push(xml_read_struct::<SubClassRule>(e, font, ctx)?.map(Box::new)),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.sub_class_rule_count = Some((self.sub_class_rule.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.sub_class_rule.iter_mut() {
			if let Some(x) = v {
				x.remap_glyphs(&mut *f)?;
			}
		}
		Ok(())
	}
}

/// `SubRule`.
#[derive(Debug, Clone, PartialEq)]
pub struct SubRule {
	/// `GlyphCount` (ComputedUShort).
	pub glyph_count: Option<u32>,
	/// `SubstCount` (ComputedUShort).
	pub subst_count: Option<u32>,
	/// `Input` (GlyphID).
	pub input: Vec<u32>,
	/// `SubstLookupRecord` (Struct).
	pub subst_lookup_record: Vec<SubstLookupRecord>,
}

impl Default for SubRule {
	fn default() -> Self {
		SubRule {
			glyph_count: Default::default(),
			subst_count: Default::default(),
			input: Default::default(),
			subst_lookup_record: Default::default(),
		}
	}
}

impl OtTable for SubRule {
	fn class_name(&self) -> &'static str {
		"SubRule"
	}
	fn decompile(r: &mut OtReader<'_>, font: &mut Font) -> Result<Self> {
		let mut t = Self::default();
		let _ = (&mut *r, &mut *font);
		t.glyph_count = Some(r.read_u16()? as u32);
		t.subst_count = Some(r.read_u16()? as u32);
		{
			let n = repeat_count(t.glyph_count.map(|v| v as i64), -1, "GlyphCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(r.read_u16()? as u32);
			}
			t.input = v;
		}
		{
			let n = repeat_count(t.subst_count.map(|v| v as i64), 0, "SubstCount")?;
			let mut v = Vec::with_capacity(n.min(4096));
			for _ in 0..n {
				v.push(SubstLookupRecord::decompile(r, font)?);
			}
			t.subst_lookup_record = v;
		}
		Ok(t)
	}
	fn compile(&self, w: &mut OtWriter<'_>, font: &mut Font) -> Result<()> {
		let _ = (&mut *w, &mut *font);
		let t = self;
		let _ = t;
		let count_glyph_count = CountRef::new("GlyphCount", 2, None);
		w.write_count_reference(count_glyph_count.clone());
		let count_subst_count = CountRef::new("SubstCount", 2, None);
		w.write_count_reference(count_subst_count.clone());
		count_glyph_count.set_value((self.input.len() as i64 - -1) as u64)?;
		w.write_array(|w| {
			for (i, item) in self.input.iter().enumerate() {
				let _ = i;
				write_glyph(w, (*item), 2)?;
			}
			Ok(())
		})?;
		count_subst_count.set_value((self.subst_lookup_record.len() as i64 - 0) as u64)?;
		for (i, item) in self.subst_lookup_record.iter().enumerate() {
			let _ = i;
			(*item).compile(w, font)?;
		}
		Ok(())
	}
	fn to_xml2(&self, xw: &mut XmlWriter, font: &mut Font) -> Result<()> {
		let _ = (&mut *xw, &mut *font);
		let t = self;
		let _ = t;
		xml_computed(xw, "GlyphCount", self.glyph_count);
		xml_computed(xw, "SubstCount", self.subst_count);
		for (i, item) in self.input.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_simple(xw, "Input", &attrs, font.glyph_name((*item))?);
		}
		for (i, item) in self.subst_lookup_record.iter().enumerate() {
			let attrs: Attrs = vec![("index", i.to_string())];
			let _ = &attrs;
			xml_struct(xw, font, Some(item), Some("SubstLookupRecord"), &attrs)?;
		}
		Ok(())
	}
	fn from_xml(&mut self, element: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<()> {
		let e = element;
		match e.name.as_str() {
			"GlyphCount" => self.glyph_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"SubstCount" => self.subst_count = Some(parse_int::<u32>(value_attr(e)?)?),
			"Input" => self.input.push(font.glyph_id(value_attr(e)?)?),
			"SubstLookupRecord" => self
				.subst_lookup_record
				.push(xml_read_struct::<SubstLookupRecord>(e, font, ctx)?.unwrap_or_default()),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		}
		let _ = (font, ctx);
		Ok(())
	}
	fn populate_defaults(&mut self, ctx: &mut XmlCtx) -> Result<()> {
		let t = &*self;
		let _ = t;
		self.glyph_count = Some((self.input.len() as i64 - -1).max(0) as u32);
		self.subst_count = Some((self.subst_lookup_record.len() as i64 - 0).max(0) as u32);
		let _ = ctx;
		Ok(())
	}
	fn remap_glyphs(&mut self, f: &mut dyn FnMut(u32) -> Result<u32>) -> Result<()> {
		for v in self.input.iter_mut() {
			*v = f(*v)?;
		}
		for v in self.subst_lookup_record.iter_mut() {
			v.remap_glyphs(&mut *f)?;
		}
		Ok(())
	}
}

