/// A lookup subtable of any lookup type of any table (`SubTable` /
/// `ExtSubTable`), dispatched on the table tag and the lookup type.
#[derive(Debug, Clone, PartialEq)]
pub enum LookupSubTable {
	/// `AlternateSubst`.
	AlternateSubst(AlternateSubst),
	/// `ChainContextPos`.
	ChainContextPos(ChainContextPos),
	/// `ChainContextSubst`.
	ChainContextSubst(ChainContextSubst),
	/// `ContextPos`.
	ContextPos(ContextPos),
	/// `ContextSubst`.
	ContextSubst(ContextSubst),
	/// `ContextualMorph`.
	ContextualMorph(ContextualMorph),
	/// `CursivePos`.
	CursivePos(CursivePos),
	/// `ExtensionPos`.
	ExtensionPos(ExtensionPos),
	/// `ExtensionSubst`.
	ExtensionSubst(ExtensionSubst),
	/// `InsertionMorph`.
	InsertionMorph(InsertionMorph),
	/// `LigatureMorph`.
	LigatureMorph(LigatureMorph),
	/// `LigatureSubst`.
	LigatureSubst(LigatureSubst),
	/// `MarkBasePos`.
	MarkBasePos(MarkBasePos),
	/// `MarkLigPos`.
	MarkLigPos(MarkLigPos),
	/// `MarkMarkPos`.
	MarkMarkPos(MarkMarkPos),
	/// `MultipleSubst`.
	MultipleSubst(MultipleSubst),
	/// `NoncontextualMorph`.
	NoncontextualMorph(NoncontextualMorph),
	/// `PairPos`.
	PairPos(PairPos),
	/// `RearrangementMorph`.
	RearrangementMorph(RearrangementMorph),
	/// `ReverseChainSingleSubst`.
	ReverseChainSingleSubst(ReverseChainSingleSubst),
	/// `SinglePos`.
	SinglePos(SinglePos),
	/// `SingleSubst`.
	SingleSubst(SingleSubst),
}

impl Default for LookupSubTable {
	fn default() -> Self {
		Self::AlternateSubst(Default::default())
	}
}

impl LookupSubTable {
	/// The class for a lookup type of a table (`lookupTypes[tag][type]`).
	pub fn decompile_for(r: &mut OtReader<'_>, font: &mut Font, lookup_type: u16) -> Result<Self> {
		Ok(match (&r.table_tag.0, lookup_type) {
			(b"GPOS", 1) => Self::SinglePos(SinglePos::decompile(r, font)?),
			(b"GPOS", 2) => Self::PairPos(PairPos::decompile(r, font)?),
			(b"GPOS", 3) => Self::CursivePos(CursivePos::decompile(r, font)?),
			(b"GPOS", 4) => Self::MarkBasePos(MarkBasePos::decompile(r, font)?),
			(b"GPOS", 5) => Self::MarkLigPos(MarkLigPos::decompile(r, font)?),
			(b"GPOS", 6) => Self::MarkMarkPos(MarkMarkPos::decompile(r, font)?),
			(b"GPOS", 7) => Self::ContextPos(ContextPos::decompile(r, font)?),
			(b"GPOS", 8) => Self::ChainContextPos(ChainContextPos::decompile(r, font)?),
			(b"GPOS", 9) => Self::ExtensionPos(ExtensionPos::decompile(r, font)?),
			(b"GSUB", 1) => Self::SingleSubst(SingleSubst::decompile(r, font)?),
			(b"GSUB", 2) => Self::MultipleSubst(MultipleSubst::decompile(r, font)?),
			(b"GSUB", 3) => Self::AlternateSubst(AlternateSubst::decompile(r, font)?),
			(b"GSUB", 4) => Self::LigatureSubst(LigatureSubst::decompile(r, font)?),
			(b"GSUB", 5) => Self::ContextSubst(ContextSubst::decompile(r, font)?),
			(b"GSUB", 6) => Self::ChainContextSubst(ChainContextSubst::decompile(r, font)?),
			(b"GSUB", 7) => Self::ExtensionSubst(ExtensionSubst::decompile(r, font)?),
			(b"GSUB", 8) => {
				Self::ReverseChainSingleSubst(ReverseChainSingleSubst::decompile(r, font)?)
			}
			(b"JSTF", 1) => Self::SinglePos(SinglePos::decompile(r, font)?),
			(b"JSTF", 2) => Self::PairPos(PairPos::decompile(r, font)?),
			(b"JSTF", 3) => Self::CursivePos(CursivePos::decompile(r, font)?),
			(b"JSTF", 4) => Self::MarkBasePos(MarkBasePos::decompile(r, font)?),
			(b"JSTF", 5) => Self::MarkLigPos(MarkLigPos::decompile(r, font)?),
			(b"JSTF", 6) => Self::MarkMarkPos(MarkMarkPos::decompile(r, font)?),
			(b"JSTF", 7) => Self::ContextPos(ContextPos::decompile(r, font)?),
			(b"JSTF", 8) => Self::ChainContextPos(ChainContextPos::decompile(r, font)?),
			(b"JSTF", 9) => Self::ExtensionPos(ExtensionPos::decompile(r, font)?),
			(b"mort", 0) => Self::RearrangementMorph(RearrangementMorph::decompile(r, font)?),
			(b"mort", 1) => Self::ContextualMorph(ContextualMorph::decompile(r, font)?),
			(b"mort", 2) => Self::LigatureMorph(LigatureMorph::decompile(r, font)?),
			(b"mort", 4) => Self::NoncontextualMorph(NoncontextualMorph::decompile(r, font)?),
			(b"mort", 5) => Self::InsertionMorph(InsertionMorph::decompile(r, font)?),
			(b"morx", 0) => Self::RearrangementMorph(RearrangementMorph::decompile(r, font)?),
			(b"morx", 1) => Self::ContextualMorph(ContextualMorph::decompile(r, font)?),
			(b"morx", 2) => Self::LigatureMorph(LigatureMorph::decompile(r, font)?),
			(b"morx", 4) => Self::NoncontextualMorph(NoncontextualMorph::decompile(r, font)?),
			(b"morx", 5) => Self::InsertionMorph(InsertionMorph::decompile(r, font)?),
			(tag, t) => {
				return Err(Error::ttlib(format!(
					"KeyError: lookup type {t} of {}",
					String::from_utf8_lossy(tag)
				)));
			}
		})
	}
	/// Reads an offset to a subtable (`SubTable.read`).
	pub fn read_offset(
		r: &mut OtReader<'_>,
		font: &mut Font,
		size: usize,
		lookup_type: u16,
	) -> Result<Option<Box<Self>>> {
		let offset = match size {
			2 => r.read_u16()? as usize,
			_ => r.read_u32()? as usize,
		};
		if offset == 0 {
			return Ok(None);
		}
		let mut sub = r.sub_reader(offset);
		Ok(Some(Box::new(Self::decompile_for(
			&mut sub,
			font,
			lookup_type,
		)?)))
	}
	/// Reads a subtable element named after its class.
	pub fn xml_read_named(e: &Element, font: &mut Font, ctx: &mut XmlCtx) -> Result<Option<Self>> {
		Ok(match e.name.as_str() {
			"AlternateSubst" => {
				xml_read_struct::<AlternateSubst>(e, font, ctx)?.map(Self::AlternateSubst)
			}
			"ChainContextPos" => {
				xml_read_struct::<ChainContextPos>(e, font, ctx)?.map(Self::ChainContextPos)
			}
			"ChainContextSubst" => {
				xml_read_struct::<ChainContextSubst>(e, font, ctx)?.map(Self::ChainContextSubst)
			}
			"ContextPos" => xml_read_struct::<ContextPos>(e, font, ctx)?.map(Self::ContextPos),
			"ContextSubst" => {
				xml_read_struct::<ContextSubst>(e, font, ctx)?.map(Self::ContextSubst)
			}
			"ContextualMorph" => {
				xml_read_struct::<ContextualMorph>(e, font, ctx)?.map(Self::ContextualMorph)
			}
			"CursivePos" => xml_read_struct::<CursivePos>(e, font, ctx)?.map(Self::CursivePos),
			"ExtensionPos" => {
				xml_read_struct::<ExtensionPos>(e, font, ctx)?.map(Self::ExtensionPos)
			}
			"ExtensionSubst" => {
				xml_read_struct::<ExtensionSubst>(e, font, ctx)?.map(Self::ExtensionSubst)
			}
			"InsertionMorph" => {
				xml_read_struct::<InsertionMorph>(e, font, ctx)?.map(Self::InsertionMorph)
			}
			"LigatureMorph" => {
				xml_read_struct::<LigatureMorph>(e, font, ctx)?.map(Self::LigatureMorph)
			}
			"LigatureSubst" => {
				xml_read_struct::<LigatureSubst>(e, font, ctx)?.map(Self::LigatureSubst)
			}
			"MarkBasePos" => xml_read_struct::<MarkBasePos>(e, font, ctx)?.map(Self::MarkBasePos),
			"MarkLigPos" => xml_read_struct::<MarkLigPos>(e, font, ctx)?.map(Self::MarkLigPos),
			"MarkMarkPos" => xml_read_struct::<MarkMarkPos>(e, font, ctx)?.map(Self::MarkMarkPos),
			"MultipleSubst" => {
				xml_read_struct::<MultipleSubst>(e, font, ctx)?.map(Self::MultipleSubst)
			}
			"NoncontextualMorph" => {
				xml_read_struct::<NoncontextualMorph>(e, font, ctx)?.map(Self::NoncontextualMorph)
			}
			"PairPos" => xml_read_struct::<PairPos>(e, font, ctx)?.map(Self::PairPos),
			"RearrangementMorph" => {
				xml_read_struct::<RearrangementMorph>(e, font, ctx)?.map(Self::RearrangementMorph)
			}
			"ReverseChainSingleSubst" => xml_read_struct::<ReverseChainSingleSubst>(e, font, ctx)?
				.map(Self::ReverseChainSingleSubst),
			"SinglePos" => xml_read_struct::<SinglePos>(e, font, ctx)?.map(Self::SinglePos),
			"SingleSubst" => xml_read_struct::<SingleSubst>(e, font, ctx)?.map(Self::SingleSubst),
			other => return Err(Error::ttx(format!("KeyError: {other:?}"))),
		})
	}
}

